-- Phase 6B Slice 1B: Recommendations Schema Parity & Initial Seed

ALTER TABLE public.recommendations
  ADD COLUMN IF NOT EXISTS source_id text UNIQUE,
  ADD COLUMN IF NOT EXISTS category text,
  ADD COLUMN IF NOT EXISTS short_description_en text,
  ADD COLUMN IF NOT EXISTS short_description_sr text,
  ADD COLUMN IF NOT EXISTS long_description_en text,
  ADD COLUMN IF NOT EXISTS long_description_sr text,
  ADD COLUMN IF NOT EXISTS image_url text,
  ADD COLUMN IF NOT EXISTS duration text,
  ADD COLUMN IF NOT EXISTS travel_time text,
  ADD COLUMN IF NOT EXISTS travel_time_minutes integer,
  ADD COLUMN IF NOT EXISTS location_en text,
  ADD COLUMN IF NOT EXISTS location_sr text,
  ADD COLUMN IF NOT EXISTS estimated_cost text,
  ADD COLUMN IF NOT EXISTS preferred_transport text,
  ADD COLUMN IF NOT EXISTS latitude double precision,
  ADD COLUMN IF NOT EXISTS longitude double precision,
  ADD COLUMN IF NOT EXISTS best_time_to_visit_en text,
  ADD COLUMN IF NOT EXISTS best_time_to_visit_sr text,
  ADD COLUMN IF NOT EXISTS insider_tip_en text,
  ADD COLUMN IF NOT EXISTS insider_tip_sr text,
  ADD COLUMN IF NOT EXISTS moods text[],
  ADD COLUMN IF NOT EXISTS ranking_score numeric,
  ADD COLUMN IF NOT EXISTS is_published boolean NOT NULL DEFAULT false;

CREATE INDEX IF NOT EXISTS idx_recommendations_source_id ON public.recommendations(source_id);
CREATE INDEX IF NOT EXISTS idx_recommendations_published ON public.recommendations(is_published);

DROP POLICY IF EXISTS select_public_recommendations ON public.recommendations;

CREATE POLICY select_public_recommendations ON public.recommendations
  FOR SELECT TO public
  USING (is_published = true);

-- Seed initial approved recommendations (102 records)
INSERT INTO public.recommendations (
  source_id, title_en, title_sr, category, short_description_en, short_description_sr,
  long_description_en, long_description_sr, image_url, duration, travel_time,
  travel_time_minutes, location_en, location_sr, estimated_cost, preferred_transport,
  latitude, longitude, best_time_to_visit_en, best_time_to_visit_sr,
  insider_tip_en, insider_tip_sr, moods, ranking_score, is_published
) VALUES
('1', 'Uvac Meanders', 'Meandri Uvca', 'Nature, Travel', 'The Uvac Gorge is home to the most dramatic river meanders in Europe. This nature reserve is the last sanctuary for the Griffon Vulture, providing breathtaking views from the Molitva lookout. A true hidden gem for those seeking pristine wilderness and natural architectural wonders in western Serbia.', 'Kanjon reke Uvac sa najdramatičnijim meandrima u Evropi i stanište beloglavog supa.', 'The Uvac Gorge is a natural masterpiece in southwestern Serbia, carved into the limestone of the Pešter plateau. The dramatic meanders of the Uvac River twist like a giant emerald serpent, a result of millions of years of geological carving. This Special Nature Reserve is the ultimate sanctuary for the Griffon Vulture (Gyps fulvus), a species brought back from the brink of extinction here. Visitors can explore the 10-meter deep usak cave system or hike to the Molitva (Prayer) lookout at 1,247m for the iconic panoramic view. The region is also famous for Sjenica cheese and the rugged hospitality of the Highland Serbs.', 'Specijalni rezervat prirode Uvac je remek-delo prirode. Poznat po svojim uklještenim meandrima i beloglavom supu, nudi neverovatne vidikovce poput Molitve. Posetioci mogu uživati u vožnji čamcem kroz meandre ili istraživanju pećinskog sistema.', '/src/assets/images/uvac_meanders_1778841048759.png', '4-6 hours', '3.5 - 4 hours', 220, 'Sjenica', 'Sjenica', '€30 - €50', 'Car + Boat', 43.3524, 19.9836, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('5', 'Zasavica Special Nature Reserve', 'Zasavica Special Nature Reserve', 'Nature, Travel', 'A protected wetland ecosystem known for rare birdlife, mangalica pigs, and the world’s most expensive cheese, made from donkey milk (Pule). A quiet, rural hidden gem for eco-friendly gastronomy.', 'A protected wetland ecosystem known for rare birdlife, mangalica pigs, and the world’s most expensive cheese, made from donkey milk (Pule). A quiet, rural hidden gem for eco-friendly gastronomy.', 'Located in the Mačva region, Zasavica is a mosaic of rare aquatic ecosystems and floodplains. While it is a sanctuary for the European beaver and over 200 bird species, it is globally famous for the Slobodan Simić donkey farm. The reserve produces "Pule," the world’s most expensive cheese (made from 60% donkey milk and 40% goat milk), priced at over €1,000 per kilogram. The "Slow Food" philosophy is central here, with visitors enjoying Mangalica pork delicacies and donkey milk liqueurs. It is a destination where ecological preservation meets the peak of niche, high-end rural gastronomy.', 'Located in the Mačva region, Zasavica is a mosaic of rare aquatic ecosystems and floodplains. While it is a sanctuary for the European beaver and over 200 bird species, it is globally famous for the Slobodan Simić donkey farm. The reserve produces "Pule," the world’s most expensive cheese (made from 60% donkey milk and 40% goat milk), priced at over €1,000 per kilogram. The "Slow Food" philosophy is central here, with visitors enjoying Mangalica pork delicacies and donkey milk liqueurs. It is a destination where ecological preservation meets the peak of niche, high-end rural gastronomy.', '/src/assets/images/zasavica_reserve_1778841114905.png', 'Half day', '1.5 hours', 90, 'Near Sremska Mitrovica', 'Near Sremska Mitrovica', '€10 - €60', 'Car', 44.9592, 19.5244, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('12', 'Banjska Stena Viewpoint', 'Banjska Stena Viewpoint', 'Nature, Travel', 'Witness Serbia’s most dramatic panorama above the emerald Drina River canyon in Tara National Park.', 'Witness Serbia’s most dramatic panorama above the emerald Drina River canyon in Tara National Park.', 'Perched at 1,065 meters above sea level, Banjska Stena (Baths Rock) offers the most dramatic vertical perspective of the Drina River canyon, which reaches depths of 1,000 meters. The viewpoint overlooks the emerald Perućac Lake, formed after the construction of the Bajina Bašta hydroelectric dam in 1966. The trail passes through dense forests of the endemic Pančić Spruce (Picea omorika), a "living fossil" from the tertiary period. At sunrise, the interplay of mountain mist and limestone cliffs creates a visual narrative of Europe''s most pristine forest wilderness.', 'Perched at 1,065 meters above sea level, Banjska Stena (Baths Rock) offers the most dramatic vertical perspective of the Drina River canyon, which reaches depths of 1,000 meters. The viewpoint overlooks the emerald Perućac Lake, formed after the construction of the Bajina Bašta hydroelectric dam in 1966. The trail passes through dense forests of the endemic Pančić Spruce (Picea omorika), a "living fossil" from the tertiary period. At sunrise, the interplay of mountain mist and limestone cliffs creates a visual narrative of Europe''s most pristine forest wilderness.', '/src/assets/images/banjska_stena_outlook_1778841232535.png', '2-4 hours', '4 hours', 240, 'Tara National Park', 'Tara National Park', '€5 - €10 (Park Fee)', 'Car + Hike', 43.9514, 19.4011, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('13', 'Đavolja Varoš (Devil’s Town)', 'Đavolja Varoš (Devil’s Town)', 'Nature, Travel', 'A natural wonder of over 200 stone pillars born from erosion and shrouded in eerie local legends.', 'A natural wonder of over 200 stone pillars born from erosion and shrouded in eerie local legends.', 'Đavolja Varoš is a geological anomaly consisting of 202 andesite stone pillars ranging from 2 to 15 meters in height. Formed by thousands of years of selective erosion of volcanic tuff, it is one of the "New Seven Wonders of Nature" candidates. The site features two highly acidic mineral springs, "Đavolja voda" (Devil''s Water) and "Crveno vrelo," with extreme pH levels of 1.5. Shrouded in legends of "petrified wedding guests," the complex offers a rare intersection of rare geological science and deep Balkan folklore.', 'Đavolja Varoš is a geological anomaly consisting of 202 andesite stone pillars ranging from 2 to 15 meters in height. Formed by thousands of years of selective erosion of volcanic tuff, it is one of the "New Seven Wonders of Nature" candidates. The site features two highly acidic mineral springs, "Đavolja voda" (Devil''s Water) and "Crveno vrelo," with extreme pH levels of 1.5. Shrouded in legends of "petrified wedding guests," the complex offers a rare intersection of rare geological science and deep Balkan folklore.', '/src/assets/images/davolja_varos_pillars_1778841249456.png', '2-3 hours', '4.5 hours', 270, 'Kuršumlija', 'Kuršumlija', '€10 - €15', 'Car', 42.9861, 21.4031, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('18', 'Đerdap Gorge', 'Đerdap Gorge', 'Nature, Travel', 'Europe’s longest river canyon and a landscape of geological grandeur. A frontier between empires, combining Roman history, Orthodox culture, and the dramatic "Iron Gates" of the Danube.', 'Europe’s longest river canyon and a landscape of geological grandeur. A frontier between empires, combining Roman history, Orthodox culture, and the dramatic "Iron Gates" of the Danube.', 'The Đerdap Gorge (Iron Gates) is the longest and largest river canyon in Europe, where the Danube breaks through the Carpathian and Balkan mountains. It encompasses four gorges (Golubac, Gospodjin Vir, Kazan, and Sip) and three basins. Historically, this was the "Limes" (frontier) of the Roman Empire, marked by the Tabula Traiana—a rock-carved plaque from 100 AD commemorating Emperor Trajan''s victory. It is a landscape of profound geographical majesty, where the river narrows to just 150 meters while reaching depths of 90 meters, creating a powerful narrative of nature vs. imperial ambition.', 'The Đerdap Gorge (Iron Gates) is the longest and largest river canyon in Europe, where the Danube breaks through the Carpathian and Balkan mountains. It encompasses four gorges (Golubac, Gospodjin Vir, Kazan, and Sip) and three basins. Historically, this was the "Limes" (frontier) of the Roman Empire, marked by the Tabula Traiana—a rock-carved plaque from 100 AD commemorating Emperor Trajan''s victory. It is a landscape of profound geographical majesty, where the river narrows to just 150 meters while reaching depths of 90 meters, creating a powerful narrative of nature vs. imperial ambition.', '/src/assets/images/djerdap_gorge_danube_1778842863362.png', 'Full day to 3 days', '2.5 - 4 hours', 180, 'Golubac–Donji Milanovac', 'Golubac–Donji Milanovac', '€90 - €500', 'Car / Private Tour', 44.6022, 22.0224, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('26', 'Stara Planina', 'Stara Planina', 'Nature', 'One of Serbia’s least urbanized mountain systems, offering remote wilderness, dramatic waterfalls, and authentic shepherd traditions.', 'One of Serbia’s least urbanized mountain systems, offering remote wilderness, dramatic waterfalls, and authentic shepherd traditions.', 'Stara Planina, part of the Balkan mountain range, is home to Serbia''s highest peak, Midžor (2,169m). This rugged landscape is famous for its "Stone Village" (Gostuša) and spectacular waterfalls like Tupavica (25m), which freezes into a crystal ice wall in winter. For the specialist traveler, it offers a rare window into the ancient pastoral life of the Pirot region, including the production of high-altitude mountain cheeses and the gathering of medicinal herbs. It remains a "wilderness of silence," providing profound geological and cultural immersion far from the density of urban Expo life.', 'Stara Planina, part of the Balkan mountain range, is home to Serbia''s highest peak, Midžor (2,169m). This rugged landscape is famous for its "Stone Village" (Gostuša) and spectacular waterfalls like Tupavica (25m), which freezes into a crystal ice wall in winter. For the specialist traveler, it offers a rare window into the ancient pastoral life of the Pirot region, including the production of high-altitude mountain cheeses and the gathering of medicinal herbs. It remains a "wilderness of silence," providing profound geological and cultural immersion far from the density of urban Expo life.', '/src/assets/images/stara_planina_landscape_1778843454764.png', '2 - 5 days', '4 hours', 240, 'Southeastern Serbia', 'Southeastern Serbia', '€40 - €180 per day', 'Car', 43.375, 22.575, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('32', 'Tara National Park', 'Tara National Park', 'Nature', 'Serbia’s strongest mountain destination for forest immersion and clean air. Dense pine forests, glacial river canyons, and the iconic Banjska Stena viewpoint.', 'Serbia’s strongest mountain destination for forest immersion and clean air. Dense pine forests, glacial river canyons, and the iconic Banjska Stena viewpoint.', 'Tara National Park is home to the "Living Fossil" Pančić Spruce (Picea omorika), discovered here in 1875 by botanist Josif Pančić. The park spans high-altitude Pešter-style pastures and the 1,000m deep Drina Canyon. It is a sanctuary for the brown bear (Ursus arctos) and rare birdlife. For the sophisticated traveler, Tara provides more than scenery; it is a profound library of European biodiversity. The absence of mass-market noise allows for a "Nature Reset" that is clinically valid for stress recovery and total digital detachment.', 'Tara National Park is home to the "Living Fossil" Pančić Spruce (Picea omorika), discovered here in 1875 by botanist Josif Pančić. The park spans high-altitude Pešter-style pastures and the 1,000m deep Drina Canyon. It is a sanctuary for the brown bear (Ursus arctos) and rare birdlife. For the sophisticated traveler, Tara provides more than scenery; it is a profound library of European biodiversity. The absence of mass-market noise allows for a "Nature Reset" that is clinically valid for stress recovery and total digital detachment.', '/src/assets/images/tara_national_park_forest_1778843961956.png', '2 - 5 days', '3.5 - 4 hours', 220, 'Western Serbia', 'Western Serbia', '€60 - €250', 'Car', 43.9114, 19.4511, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('46', 'Resava Cave', 'Resava Cave', 'Nature, Travel', 'One of the Balkans’ finest accessible cave systems, featuring dramatic calcite formations and underground halls millions of years old.', 'One of the Balkans’ finest accessible cave systems, featuring dramatic calcite formations and underground halls millions of years old.', 'Discovered in 1962, Resava Cave (Resavska pećina) is a 4.5km long subterranean system, with 800 meters of illuminated paths for visitors. Its mineral chambers, formed over 80 million years, feature "The Hanging Ornaments" and "The Coral Canal," glowing with white and red calcite. The temperature remains a constant 7°C, providing a visceral sensory reset. Paired with the Despot Stefan Lazarević’s Manasija Monastery nearby, it offers an intellectually dense day trip that explores the geological and spiritual foundations of the Central Serbian landscape.', 'Discovered in 1962, Resava Cave (Resavska pećina) is a 4.5km long subterranean system, with 800 meters of illuminated paths for visitors. Its mineral chambers, formed over 80 million years, feature "The Hanging Ornaments" and "The Coral Canal," glowing with white and red calcite. The temperature remains a constant 7°C, providing a visceral sensory reset. Paired with the Despot Stefan Lazarević’s Manasija Monastery nearby, it offers an intellectually dense day trip that explores the geological and spiritual foundations of the Central Serbian landscape.', '/src/assets/images/resava_cave_formations_1778845766990.png', '1 - 2 hours', '2 hours', 120, 'Central-Eastern Serbia', 'Central-Eastern Serbia', '€5 - €10', 'Car', 44.1232, 21.6294, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('48', 'Lazarev Canyon', 'Lazarev Canyon', 'Nature', 'One of Serbia’s wildest and deepest canyons. An untamed landscape of dense forests and limestone cliffs for authentic wilderness seekers.', 'One of Serbia’s wildest and deepest canyons. An untamed landscape of dense forests and limestone cliffs for authentic wilderness seekers.', 'Lazarev Canyon is the deepest and longest canyon in Eastern Serbia, featuring 4.5km of near-vertical limestone cliffs and untamed biodiversity. It is home to over 70 caves, including the spectacular Lazareva pećina, which once served as a sanctuary for outlaws (Hajduks) during Ottoman rule. The canyon is a stronghold for the rare European Brown Bear and unique flora. For the high-performing traveler seeking total topographical and digital detox, Lazarev offers a raw, non-commercialized wilderness experience that visually rivals the American Southwest.', 'Lazarev Canyon is the deepest and longest canyon in Eastern Serbia, featuring 4.5km of near-vertical limestone cliffs and untamed biodiversity. It is home to over 70 caves, including the spectacular Lazareva pećina, which once served as a sanctuary for outlaws (Hajduks) during Ottoman rule. The canyon is a stronghold for the rare European Brown Bear and unique flora. For the high-performing traveler seeking total topographical and digital detox, Lazarev offers a raw, non-commercialized wilderness experience that visually rivals the American Southwest.', '/src/assets/images/lazarev_canyon_wild_1778845803839.png', 'Full day to 2 days', '3.5 hours', 210, 'Near Bor', 'Near Bor', '€30 - €150', 'Car', 44.0333, 21.9667, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('62', 'Carska Bara Wetlands', 'Carska Bara Wetlands', 'Nature, Travel', 'One of the Balkans’ richest wetland ecosystems. A sanctuary for hundreds of bird species amidst the winding canals of the Pannonian Plain.', 'One of the Balkans’ richest wetland ecosystems. A sanctuary for hundreds of bird species amidst the winding canals of the Pannonian Plain.', 'Carska Bara (Imperial Marsh) is a Ramsar-protected wetland at the confluence of the Begej and Tisza rivers. It is a mosaic of reeds, willow forests, and Pannonian steppes (Pustara), home to over 250 bird species including the rare Purple Heron and White-tailed Eagle. Navigating the "Old Begej" canal by boat offers a sensory journey through the silent, prehistoric heart of the Pannonian Plain. For the high-performing traveler, it provides the ultimate "Quiet Decompression" experience, where nature’s slow rhythms replace the density of urban social performance.', 'Carska Bara (Imperial Marsh) is a Ramsar-protected wetland at the confluence of the Begej and Tisza rivers. It is a mosaic of reeds, willow forests, and Pannonian steppes (Pustara), home to over 250 bird species including the rare Purple Heron and White-tailed Eagle. Navigating the "Old Begej" canal by boat offers a sensory journey through the silent, prehistoric heart of the Pannonian Plain. For the high-performing traveler, it provides the ultimate "Quiet Decompression" experience, where nature’s slow rhythms replace the density of urban social performance.', '/src/assets/images/carska_bara_wetlands_birds_aerial_1778846483752.png', 'Half day to full day', '1.5 hours', 90, 'Near Zrenjanin', 'Near Zrenjanin', '€10 - €40', 'Car', 45.25, 20.3833, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('75', 'Tara Forest Reset & Banjska Stena Hike', 'Tara Forest Reset & Banjska Stena Hike', 'Nature', 'Banjska Stena offers one of the most restorative short hikes in the Balkans. Dense pine forests suddenly open above the Drina canyon.', 'Banjska Stena offers one of the most restorative short hikes in the Balkans. Dense pine forests suddenly open above the Drina canyon.', 'The Banjska Stena trail is a masterclass in "Forest Reset" (Shinrin-yoku), passing through dense forests of the endemic Pančić Spruce (Picea omorika), a living fossil from the Tertiary era. The final viewpoint overlooking the Drina Canyon—1,000 meters deep—offers one of the most dramatic topographic releases in the Balkans. It is the ideal "Sensory Decompression" for high-performing professionals, where the absence of mass-market noise allows for a profound psychological reset. The route is physically accessible yet offers the visual scale of a high-alpine wilderness.', 'The Banjska Stena trail is a masterclass in "Forest Reset" (Shinrin-yoku), passing through dense forests of the endemic Pančić Spruce (Picea omorika), a living fossil from the Tertiary era. The final viewpoint overlooking the Drina Canyon—1,000 meters deep—offers one of the most dramatic topographic releases in the Balkans. It is the ideal "Sensory Decompression" for high-performing professionals, where the absence of mass-market noise allows for a profound psychological reset. The route is physically accessible yet offers the visual scale of a high-alpine wilderness.', '/src/assets/images/tara_forest_reset_hike_1778848171218.png', 'Weekend to 3 days', '4 hours', 240, 'Tara National Park', 'Tara National Park', '€80 - €300 per night', 'Car / Private Transfer', 43.9167, 19.3833, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('76', 'Drina River Soft Rafting & Riverside Lodges', 'Drina River Soft Rafting & Riverside Lodges', 'Nature', 'Low-intensity rafting focused on immersion in canyon landscapes and cold mountain water.', 'Low-intensity rafting focused on immersion in canyon landscapes and cold mountain water.', 'Soft Rafting on the Drina River focuses on the emerald tranquility of the canyon rather than high-octane adventure. Key landmarks on this route include the world-famous "Kućica na steni" (The House on the Rock), a symbol of Balkan resilience since 1968. Floating lunches on private wooden rafts, featuring local trout and rakija, emphasize a culture of unhurried social dialogue. It is a total "Psychological Contrast" to urban environments, offering a serene, sensory-rich journey through one of Europe’s most pristine river ecosystems.', 'Soft Rafting on the Drina River focuses on the emerald tranquility of the canyon rather than high-octane adventure. Key landmarks on this route include the world-famous "Kućica na steni" (The House on the Rock), a symbol of Balkan resilience since 1968. Floating lunches on private wooden rafts, featuring local trout and rakija, emphasize a culture of unhurried social dialogue. It is a total "Psychological Contrast" to urban environments, offering a serene, sensory-rich journey through one of Europe’s most pristine river ecosystems.', '/src/assets/images/drina_soft_rafting_river_1778848188991.png', 'Full day to weekend', '3.5 - 4 hours', 220, 'Western Serbia / Drina', 'Western Serbia / Drina', '€80 - €250', 'Car / Private Transfer', 43.9667, 19.3333, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('77', 'Durmitor Mountain & Black Lake Extension', 'Durmitor Mountain & Black Lake Extension', 'Nature, Travel', 'Glacial lakes, moderate hiking, and limestone peaks in a UNESCO-protected landscape.', 'Glacial lakes, moderate hiking, and limestone peaks in a UNESCO-protected landscape.', 'Durmitor National Park is a UNESCO-protected limestone massif in Northern Montenegro that perfectly complements a Western Serbian itinerary. It features 18 glacial lakes known as "Mountain Eyes," with the Black Lake (Crno Jezero) being the most iconic. The region is crossed by the Tara River Bridge (Đurđevića Tara), which was the largest arched concrete bridge in Europe when completed in 1940. It offers a visually spectacular mountain sanctuary with a Central European alpine atmosphere, perfect for the high-status traveler seeking ecological and historical depth.', 'Durmitor National Park is a UNESCO-protected limestone massif in Northern Montenegro that perfectly complements a Western Serbian itinerary. It features 18 glacial lakes known as "Mountain Eyes," with the Black Lake (Crno Jezero) being the most iconic. The region is crossed by the Tara River Bridge (Đurđevića Tara), which was the largest arched concrete bridge in Europe when completed in 1940. It offers a visually spectacular mountain sanctuary with a Central European alpine atmosphere, perfect for the high-status traveler seeking ecological and historical depth.', '/src/assets/images/durmitor_mountain_black_lake_1778848206164.png', '3 - 5 days', '6 - 7 hours', 390, 'Northern Montenegro', 'Northern Montenegro', '€120 - €450 per night', 'Car / Private Transfer', 43.1556, 19.1219, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('78', 'Fruška Gora E-Bike Wine Routes', 'Fruška Gora E-Bike Wine Routes', 'Nature, Gastronomy', 'Gentle physical activity combined with gastronomy and wine culture through forest roads and vineyards.', 'Gentle physical activity combined with gastronomy and wine culture through forest roads and vineyards.', 'E-Bike routes through the "Holy Mountain" of Fruška Gora provide a sophisticated blend of physical movement and gastronomic discovery. The circuit connects the 16 monasteries with boutique wineries in the "Wine Capital" of Irig, specializing in "Bermet"—the legendary spiced wine of the region. The routes utilize paved forest roads and vineyard paths, making them accessible to high-performing business travelers seeking a "Deep Landscape" reset. It remains the most refined outdoor gastro-route in Northern Serbia, blending history, viticulture, and ecological health.', 'E-Bike routes through the "Holy Mountain" of Fruška Gora provide a sophisticated blend of physical movement and gastronomic discovery. The circuit connects the 16 monasteries with boutique wineries in the "Wine Capital" of Irig, specializing in "Bermet"—the legendary spiced wine of the region. The routes utilize paved forest roads and vineyard paths, making them accessible to high-performing business travelers seeking a "Deep Landscape" reset. It remains the most refined outdoor gastro-route in Northern Serbia, blending history, viticulture, and ecological health.', '/src/assets/images/fruska_gora_ebike_route_1778848222663.png', 'Full day to weekend', '1 - 1.5 hours', 75, 'Fruška Gora Region', 'Fruška Gora Region', '€60 - €220 per day', 'Car + E-bike rental', 45.15, 19.75, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('79', 'Drina Regatta Private River Experience', 'Drina Regatta Private River Experience', 'Nature', 'Curated floating experiences through emerald canyons, cold river swimming, and floating lunches.', 'Curated floating experiences through emerald canyons, cold river swimming, and floating lunches.', 'The Private Drina Regatta experience is a curated floating ritual through the 1,000m deep Drina Canyon. Unlike the high-density public event, these private wooden "Splavy" (Rafts) focus on the emerald tranquility of the river, incorporating floating kitchens and cold river swimming stops. It represents the "Social Frontier" of the Drina, where the city''s elite come to decompress in total privacy. Surrounded by the "Profound Green" of the forest, it provides an intellectually and sensory-rich contrast to the high-tempo urban environment of Belgrade.', 'The Private Drina Regatta experience is a curated floating ritual through the 1,000m deep Drina Canyon. Unlike the high-density public event, these private wooden "Splavy" (Rafts) focus on the emerald tranquility of the river, incorporating floating kitchens and cold river swimming stops. It represents the "Social Frontier" of the Drina, where the city''s elite come to decompress in total privacy. Surrounded by the "Profound Green" of the forest, it provides an intellectually and sensory-rich contrast to the high-tempo urban environment of Belgrade.', '/src/assets/images/drina_regatta_private_float_1778848239635.png', 'Full day to weekend', '4 hours', 240, 'Bajina Bašta / Drina', 'Bajina Bašta / Drina', '€120 - €450', 'Car / Private Transfer', 43.9667, 19.5667, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('80', 'Ada Ciganlija Open-Water Lifestyle', 'Ada Ciganlija Open-Water Lifestyle', 'Nature', 'Belgrade’s outdoor movement zone: cycling, kayaking, paddleboarding, and forest walking within the city.', 'Belgrade’s outdoor movement zone: cycling, kayaking, paddleboarding, and forest walking within the city.', 'Ada Ciganlija, the "Sea of Belgrade," is a Blue Flag-certified peninsula on the Sava River that serves as the city''s primary outdoor movement zone. It features a 7km-long artificial lake and 9km of beaches, supported by intensive forest trails and high-spec cycling paths. Historically a vital recreation spot for the working class, it has evolved into a sophisticated urban "Air Spa" where the city''s residents engage in "Ritual Fitness." It offers the most efficient "Sensory Reset" for Expo visitors, providing immediate access to open-water kayaking and forest immersion.', 'Ada Ciganlija, the "Sea of Belgrade," is a Blue Flag-certified peninsula on the Sava River that serves as the city''s primary outdoor movement zone. It features a 7km-long artificial lake and 9km of beaches, supported by intensive forest trails and high-spec cycling paths. Historically a vital recreation spot for the working class, it has evolved into a sophisticated urban "Air Spa" where the city''s residents engage in "Ritual Fitness." It offers the most efficient "Sensory Reset" for Expo visitors, providing immediate access to open-water kayaking and forest immersion.', '/src/assets/images/ada_ciganlija_lifestyle_1778848256252.png', '2 - 6 hours', 'Urban access', 15, 'Belgrade', 'Belgrade', '€10 - €80', 'Taxi / Bike', 44.7833, 20.4, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('81', 'Via Ferrata Kablar — Soft Vertical Adventure', 'Via Ferrata Kablar — Soft Vertical Adventure', 'Nature, Travel', 'Beginner-friendly secured climbing routes offering dramatic panoramic views of the Ovčar-Kablar Gorge.', 'Beginner-friendly secured climbing routes offering dramatic panoramic views of the Ovčar-Kablar Gorge.', 'Via Ferrata Kablar is a secured climbing route in the Ovčar-Kablar Gorge, a region known as the "Serbian Holy Mountain" due to its 10 medieval monasteries. The route provides a controlled vertical challenge on the limestone cliffs of Mount Kablar, offering a 360-degree topographical release above the meanders of the West Morava river. It is designed for active travelers seeking a "Soft Adventure" that combines physical movement with a profound historical and spiritual landscape, perfectly paired with the nearby thermal waters of Ovčar Banja.', 'Via Ferrata Kablar is a secured climbing route in the Ovčar-Kablar Gorge, a region known as the "Serbian Holy Mountain" due to its 10 medieval monasteries. The route provides a controlled vertical challenge on the limestone cliffs of Mount Kablar, offering a 360-degree topographical release above the meanders of the West Morava river. It is designed for active travelers seeking a "Soft Adventure" that combines physical movement with a profound historical and spiritual landscape, perfectly paired with the nearby thermal waters of Ovčar Banja.', '/src/assets/images/via_ferrata_kablar_climb_1778848271890.png', 'Half day to weekend', '2.5 hours', 150, 'Ovčar-Kablar Gorge', 'Ovčar-Kablar Gorge', '€50 - €180', 'Car / Private Transfer', 43.9, 20.2167, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('82', 'Horseback Riding on Zlatibor Highlands', 'Horseback Riding on Zlatibor Highlands', 'Nature, Travel', 'Curated riding experiences across rolling mountain pastures, pine landscapes, and village trails.', 'Curated riding experiences across rolling mountain pastures, pine landscapes, and village trails.', 'The Zlatibor Highlands (900–1,100 meters) have a long-standing tradition of equestrian culture, suited to the rolling pastures and pine forests of Western Serbia. Curated riding experiences follow historic village trails, bypassing the commercial center for the quiet authenticity of the high plateau. The low-intensity effort combined with the "Air Spa" microclimate makes it a restorative choice for the high-performing traveler, offering a sensory immersion in the Pannonian-Dinaric transition zone.', 'The Zlatibor Highlands (900–1,100 meters) have a long-standing tradition of equestrian culture, suited to the rolling pastures and pine forests of Western Serbia. Curated riding experiences follow historic village trails, bypassing the commercial center for the quiet authenticity of the high plateau. The low-intensity effort combined with the "Air Spa" microclimate makes it a restorative choice for the high-performing traveler, offering a sensory immersion in the Pannonian-Dinaric transition zone.', '/src/assets/images/zlatibor_horseback_riding_1778848289413.png', 'Half day to weekend', '3.5 hours', 210, 'Zlatibor Region', 'Zlatibor Region', '€50 - €250', 'Car / Private Transfer', 43.7167, 19.7, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('84', 'Sunset Kayaking Beneath Belgrade Fortress', 'Sunset Kayaking Beneath Belgrade Fortress', 'Nature', 'A meditative urban paddling experience observing the confluence, floating clubs, and fortress walls from the water.', 'A meditative urban paddling experience observing the confluence, floating clubs, and fortress walls from the water.', 'Kayaking at the confluence of the Sava and Danube rivers offers a unique topographical perspective on Belgrade’s 2,000-year history. Navigating beneath the 18th-century Austrian and Ottoman walls of the Kalemegdan Fortress, paddlers witness the city’s transition from a military frontier to a vibrant modern capital. The sunset ritual on the water provides a profound sensory decompression, where the scale of the rivers and the illuminated "Victor" monument create a meditative urban escape for the sophisticated traveler.', 'Kayaking at the confluence of the Sava and Danube rivers offers a unique topographical perspective on Belgrade’s 2,000-year history. Navigating beneath the 18th-century Austrian and Ottoman walls of the Kalemegdan Fortress, paddlers witness the city’s transition from a military frontier to a vibrant modern capital. The sunset ritual on the water provides a profound sensory decompression, where the scale of the rivers and the illuminated "Victor" monument create a meditative urban escape for the sophisticated traveler.', '/src/assets/images/belgrade_sunset_kayaking_1778848325953.png', '2 - 4 hours', 'Urban access', 10, 'Confluence, Belgrade', 'Confluence, Belgrade', '€40 - €150', 'On Foot / Taxi', 44.825, 20.45, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('85', 'Splavarenje Tarom — Tara River Rafting', 'Splavarenje Tarom — Tara River Rafting', 'Nature', 'Rafting and floating experiences in Europe’s deepest canyon. A transition into silence, pine forests, and turquoise water.', 'Rafting and floating experiences in Europe’s deepest canyon. A transition into silence, pine forests, and turquoise water.', 'Rafting the Tara River, in a canyon reaching depths of 1,333 meters, is an immersion in a UNESCO-protected wilderness. The "Splavarenje" tradition—originally used by loggers to transport timber—has evolved into a high-end ecological adventure. The turquoise "Mountain Eye" waters and the high limestone walls create a total digital and sensory detox. It remains the most dramatic natural border of the Balkan region, requiring a transition into the slow, rhythmic time of the deep forest and its prehistoric pine landscapes.', 'Rafting the Tara River, in a canyon reaching depths of 1,333 meters, is an immersion in a UNESCO-protected wilderness. The "Splavarenje" tradition—originally used by loggers to transport timber—has evolved into a high-end ecological adventure. The turquoise "Mountain Eye" waters and the high limestone walls create a total digital and sensory detox. It remains the most dramatic natural border of the Balkan region, requiring a transition into the slow, rhythmic time of the deep forest and its prehistoric pine landscapes.', '/src/assets/images/tara_river_canyon_rafting_1778848341451.png', 'Weekend to 4 days', '5 - 7 hours', 360, 'Tara Canyon Region', 'Tara Canyon Region', '€150 - €500+', 'Car / Private Transfer', 43.35, 18.9667, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('2', 'Manasija Monastery', 'Manastir Manasija', 'History, Travel', 'Manasija, also known as Resava, is a fortified monastery complex surrounded by 11 massive towers. Built in the early 15th century, it was a center for literature and culture during the Serbian Despotate. Its frescoes are among the most beautiful examples of medieval Serbian art.', 'Utvrđeni manastirski kompleks okružen sa 11 masivnih kula, centar Resavske škole.', 'Founded by Despot Stefan Lazarević between 1407 and 1418, Manasija (Resava) is a pinnacle of the "Morava School" of architecture. Its most striking feature is the massive fortification system consisting of 11 towers, with the tallest being the Despot''s Tower (Despotova kula). The Church of the Holy Trinity houses frescoes of the "Holy Warriors" which are considered among the finest examples of 15th-century Byzantine art. For decades, the monastery was home to the Resava Scriptorium, where medieval manuscripts were meticulously translated and preserved, serving as the intellectual lighthouse of the Balkans during the Ottoman advance.', 'Manastir Manasija, zadužbina despota Stefana Lazarevića, jedan je od najznačajnijih spomenika srpske srednjovekovne kulture. Ono što izdvaja Manasiju je njen odbrambeni sistem od 11 kula spojenih bedemima. Freske u crkvi Svete Trojice spadaju u najviše domete vizantijske umetnosti 15. veka.', '/src/assets/images/manasija_monastery_1778841065960.png', '2-3 hours', '1.5 - 2 hours', 100, 'Despotovac', 'Despotovac', '€10 - €20', 'Car', 44.1017, 21.4697, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('7', 'Nikola Tesla Museum', 'Nikola Tesla Museum', 'History', 'Explore the legacy of the genius who "invented the 20th century." This museum houses Tesla’s original inventions, personal archive, and ashes.', 'Explore the legacy of the genius who "invented the 20th century." This museum houses Tesla’s original inventions, personal archive, and ashes.', 'Established in 1952, this museum is the global guardian of Tesla’s personal effects and scientific legacy. Housed in a beautiful 1927 villa designed by Dragiša Brašovan, it contains over 160,000 original documents, 2,000 books, and Tesla''s ashes in a golden orb. Visitors can experience working replicas of his induction motors and the 500,000-volt Tesla coil. The collection was included in UNESCO’s "Memory of the World" Register in 2003, honoring the man whose alternating current (AC) system pioneered the modern electrical age. It is a masterclass in history, science, and the power of human imagination.', 'Established in 1952, this museum is the global guardian of Tesla’s personal effects and scientific legacy. Housed in a beautiful 1927 villa designed by Dragiša Brašovan, it contains over 160,000 original documents, 2,000 books, and Tesla''s ashes in a golden orb. Visitors can experience working replicas of his induction motors and the 500,000-volt Tesla coil. The collection was included in UNESCO’s "Memory of the World" Register in 2003, honoring the man whose alternating current (AC) system pioneered the modern electrical age. It is a masterclass in history, science, and the power of human imagination.', '/src/assets/images/tesla_museum_ext_1778841146661.png', '1-2 hours', '15 - 20 minutes', 20, 'Belgrade, Vračar', 'Belgrade, Vračar', '€8', 'Taxi / Tram', 44.8051, 20.4707, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('16', 'Felix Romuliana', 'Felix Romuliana', 'History, Travel', 'UNESCO-listed imperial palace built by Emperor Galerius, featuring exquisite Roman floor mosaics.', 'UNESCO-listed imperial palace built by Emperor Galerius, featuring exquisite Roman floor mosaics.', 'Felix Romuliana (Gamzigrad) was the imperial residence of Emperor Galerius (reigned 293–311 AD), built as his retirement palace and named after his mother, Romula. This UNESCO site features massive fortifications with 20 towers and remains of two grand temples. Its crowning glory is the collection of floor mosaics—notably the "Dionysus" and "Venators"—which showcase the highest peak of late Roman craftsmanship. It is a physical monument to a Tetrarchy-era emperor who rose from an Illyrian shepherd to the ruler of the Roman world.', 'Felix Romuliana (Gamzigrad) was the imperial residence of Emperor Galerius (reigned 293–311 AD), built as his retirement palace and named after his mother, Romula. This UNESCO site features massive fortifications with 20 towers and remains of two grand temples. Its crowning glory is the collection of floor mosaics—notably the "Dionysus" and "Venators"—which showcase the highest peak of late Roman craftsmanship. It is a physical monument to a Tetrarchy-era emperor who rose from an Illyrian shepherd to the ruler of the Roman world.', '/src/assets/images/felix_romuliana_ruins_1778841314415.png', '2-3 hours', '3.5 hours', 210, 'Gamzigrad, Zaječar', 'Gamzigrad, Zaječar', '€5 - €10', 'Car', 43.9122, 22.1864, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('17', 'Viminacium Archaeological Park', 'Viminacium Archaeological Park', 'History, Travel', 'Ancient Roman provincial capital featuring preserved Roman ships and a million-year-old mammoth skeleton.', 'Ancient Roman provincial capital featuring preserved Roman ships and a million-year-old mammoth skeleton.', 'Viminacium was the capital of the Roman province of Moesia Superior and a vital military camp (Castrum) for the Legio VII Claudia. At its peak, it housed 40,000 citizens and hosted numerous Roman emperors. The site includes a massive amphitheater, thermae (baths) with intricate floor heating, and a spectacular mausoleum. A unique addition is the "Mammoth Park," which preserves "Vika," a five-million-year-old mammoth skeleton found 27 meters underground. It offers an intellectually dense journey through Roman urbanism and prehistoric natural history.', 'Viminacium was the capital of the Roman province of Moesia Superior and a vital military camp (Castrum) for the Legio VII Claudia. At its peak, it housed 40,000 citizens and hosted numerous Roman emperors. The site includes a massive amphitheater, thermae (baths) with intricate floor heating, and a spectacular mausoleum. A unique addition is the "Mammoth Park," which preserves "Vika," a five-million-year-old mammoth skeleton found 27 meters underground. It offers an intellectually dense journey through Roman urbanism and prehistoric natural history.', '/src/assets/images/viminacium_archaeology_1778841330074.png', '2-4 hours', '1.5 hours', 90, 'Kostolac, Požarevac', 'Kostolac, Požarevac', '€8 - €12', 'Car', 44.7333, 21.2333, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('19', 'Golubac Fortress', 'Golubac Fortress', 'History, Travel', 'One of the Balkans’ finest medieval river fortifications, standing guard at the Iron Gates. A visual masterpiece of military architecture on the Danube bank.', 'One of the Balkans’ finest medieval river fortifications, standing guard at the Iron Gates. A visual masterpiece of military architecture on the Danube bank.', 'Standing at the gateway to the Iron Gates, Golubac Fortress is a masterpiece of medieval military architecture. It consists of ten towers connected by massive ramparts, built primarily in the 14th century. Historically contested between the Serbs, Hungarians, and Ottomans, it was significantly expanded by Despot Stefan Lazarević in 1403. The fortress is divided into several zones, including the "forbidden zone" for higher-status visitors. After a major 2019 restoration, it serves as a world-class historical park, offering a visceral sense of the "Danube Front" that protected Europe for centuries.', 'Standing at the gateway to the Iron Gates, Golubac Fortress is a masterpiece of medieval military architecture. It consists of ten towers connected by massive ramparts, built primarily in the 14th century. Historically contested between the Serbs, Hungarians, and Ottomans, it was significantly expanded by Despot Stefan Lazarević in 1403. The fortress is divided into several zones, including the "forbidden zone" for higher-status visitors. After a major 2019 restoration, it serves as a world-class historical park, offering a visceral sense of the "Danube Front" that protected Europe for centuries.', '/src/assets/images/golubac_fortress_danube_1778842880053.png', '2-4 hours', '2 hours 15 mins', 135, 'Golubac', 'Golubac', '€5 - €250', 'Car / River Cruise', 44.6611, 21.6781, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('20', 'Lepenski Vir', 'Lepenski Vir', 'History, Travel', 'Europe’s most important Mesolithic archaeological site, dating back 8,000 years. Discover enigmatic prehistoric sculptures and early river civilization patterns.', 'Europe’s most important Mesolithic archaeological site, dating back 8,000 years. Discover enigmatic prehistoric sculptures and early river civilization patterns.', 'Lepenski Vir, discovered in 1967 by Dragoslav Srejović, is the world''s oldest planned settlement, dating to 9500-6000 BCE. The culture is unique for its trapezoidal house foundations and the "fish-like" sandstone idols, which are the oldest monumental sculptures in Europe. These artistic expressions reflect a deep religious connection to the Danube River. The hyper-modern museum protects the original excavation site while offering a sophisticated, light-filled narrative of how the first Europeans transitions from hunting to a settled, ritualistic river civilization.', 'Lepenski Vir, discovered in 1967 by Dragoslav Srejović, is the world''s oldest planned settlement, dating to 9500-6000 BCE. The culture is unique for its trapezoidal house foundations and the "fish-like" sandstone idols, which are the oldest monumental sculptures in Europe. These artistic expressions reflect a deep religious connection to the Danube River. The hyper-modern museum protects the original excavation site while offering a sophisticated, light-filled narrative of how the first Europeans transitions from hunting to a settled, ritualistic river civilization.', '/src/assets/images/lepenski_vir_archaeology_1778842894027.png', '1.5-3 hours', '3 hours', 180, 'Near Donji Milanovac', 'Near Donji Milanovac', '€5 - €180', 'Car / Guided Tour', 44.5572, 22.0258, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('36', 'Kovačica Naïve Art', 'Kovačica Naïve Art', 'History', 'Internationally recognized folk-art movement within the Slovak minority community. Vibrant, dreamlike village scenes that have captivated global collectors.', 'Internationally recognized folk-art movement within the Slovak minority community. Vibrant, dreamlike village scenes that have captivated global collectors.', 'Kovačica is a global phenomenon where the local Slovak minority has fostered a unique school of Naïve Art since the 1940s. Its most famous artist, Zuzana Halupova (1925–2001), was honored by UNICEF for her vibrant, dreamlike village scenes. The paintings, characterized by oversized figures and vivid rural landscapes, provide a visceral connection to the Pannonian agricultural soul. For the collector and cultural historian, Kovačica offers an organic art movement that has remained authentic, sustainable, and intellectually independent of modern urban trends.', 'Kovačica is a global phenomenon where the local Slovak minority has fostered a unique school of Naïve Art since the 1940s. Its most famous artist, Zuzana Halupova (1925–2001), was honored by UNICEF for her vibrant, dreamlike village scenes. The paintings, characterized by oversized figures and vivid rural landscapes, provide a visceral connection to the Pannonian agricultural soul. For the collector and cultural historian, Kovačica offers an organic art movement that has remained authentic, sustainable, and intellectually independent of modern urban trends.', '/src/assets/images/kovacica_naive_art_gallery_1778844026577.png', 'Half day', '1.5 hours', 90, 'South Banat Region', 'South Banat Region', '€50 - €5000+', 'Car', 45.1114, 20.6214, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('38', 'Ovčar-Kablar Gorge', 'Ovčar-Kablar Gorge', 'History', 'The "Serbian Mount Athos"—a concentration of ancient monasteries tucked into a dramatic river gorge. A spiritual landscape for contemplative travel.', 'The "Serbian Mount Athos"—a concentration of ancient monasteries tucked into a dramatic river gorge. A spiritual landscape for contemplative travel.', 'The Ovčar-Kablar Gorge, where the West Morava River carves its way through steep cliffs, is home to ten medieval monasteries, earning it the title of the "Serbian Mount Athos." Significant sites like Blagoveštenje (Annunciation) and Nikolje (St. Nicholas) were centers of literacy during the Ottoman centuries. Today, the gorge is protected as a Landscape of Exceptional Features. For the pensive traveler, it offers a profound intersection of high-altitude hiking, thermal water recovery, and the spiritual silence of centuries-old Orthodox monastic traditions.', 'The Ovčar-Kablar Gorge, where the West Morava River carves its way through steep cliffs, is home to ten medieval monasteries, earning it the title of the "Serbian Mount Athos." Significant sites like Blagoveštenje (Annunciation) and Nikolje (St. Nicholas) were centers of literacy during the Ottoman centuries. Today, the gorge is protected as a Landscape of Exceptional Features. For the pensive traveler, it offers a profound intersection of high-altitude hiking, thermal water recovery, and the spiritual silence of centuries-old Orthodox monastic traditions.', '/src/assets/images/ovcar_kablar_gorge_monastery_1778844065335.png', 'Full day to weekend', '2.5 hours', 150, 'Near Čačak', 'Near Čačak', '€40 - €180', 'Car', 43.9014, 20.1836, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('44', 'Sirogojno Open-Air Museum', 'Sirogojno Open-Air Museum', 'History, Travel', 'An authentic ethnographic village preserving 19th-century mountain life. Home to the legendary Sirogojno knitwear tradition.', 'An authentic ethnographic village preserving 19th-century mountain life. Home to the legendary Sirogojno knitwear tradition.', 'The "Staro Selo" museum in Sirogojno is a living laboratory of Dinaric-style mountain culture. Over 40 authentic wooden "Brvnara" (log cabins), some dating back 150 years, have been relocated to preserve the Zlatibor region''s architectural soul. The village is also the home of the "Sirogojno Style" knitwear movement, which gained global fame in the 1970s through collaborations with Parisian fashion houses. It is a destination where pre-industrial survival skills and high-end artisanal heritage intersect, offering a profound sense of cultural continuity.', 'The "Staro Selo" museum in Sirogojno is a living laboratory of Dinaric-style mountain culture. Over 40 authentic wooden "Brvnara" (log cabins), some dating back 150 years, have been relocated to preserve the Zlatibor region''s architectural soul. The village is also the home of the "Sirogojno Style" knitwear movement, which gained global fame in the 1970s through collaborations with Parisian fashion houses. It is a destination where pre-industrial survival skills and high-end artisanal heritage intersect, offering a profound sense of cultural continuity.', '/src/assets/images/sirogojno_ethno_village_1778845118794.png', '2 - 3 hours', '3.5 - 4 hours', 220, 'Zlatibor Region', 'Zlatibor Region', '€5 - €250', 'Car', 43.6822, 19.8786, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('45', 'Niš Fortress', 'Niš Fortress', 'History, Travel', 'A legendary Ottoman fortress built on Roman foundations in the birthplace of Constantine the Great. A cultural crossroads of the southern Balkans.', 'A legendary Ottoman fortress built on Roman foundations in the birthplace of Constantine the Great. A cultural crossroads of the southern Balkans.', 'Niš Fortress is a palimpsest of Balkan history, with the current 1723 Ottoman structure standing over Roman Naissus and Byzantine ruins. Key landmarks inside include the Bali-beg Mosque (16th century), the Roman lapidarium, and the atmospheric Turkish Hamam. As the birthplace of Constantine the Great, Niš reflects a deep, southern-crossroads identity. The fortress now hosts the Nišville International Jazz Festival, where ancient stone ramparts serve as an acoustically and visually stunning stage for contemporary global culture.', 'Niš Fortress is a palimpsest of Balkan history, with the current 1723 Ottoman structure standing over Roman Naissus and Byzantine ruins. Key landmarks inside include the Bali-beg Mosque (16th century), the Roman lapidarium, and the atmospheric Turkish Hamam. As the birthplace of Constantine the Great, Niš reflects a deep, southern-crossroads identity. The fortress now hosts the Nišville International Jazz Festival, where ancient stone ramparts serve as an acoustically and visually stunning stage for contemporary global culture.', '/src/assets/images/nis_fortress_stambol_gate_1778845134540.png', '1 - 2 days', '2.5 - 3 hours', 160, 'Niš, Southern Serbia', 'Niš, Southern Serbia', '€40 - €180', 'Car / Train / Flight', 43.3283, 21.8953, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('49', 'Mediana Archaeological Site', 'Mediana Archaeological Site', 'History', 'The imperial estate of Constantine the Great. A window into the elite Roman life of ancient Naissus through stunning floor mosaics.', 'The imperial estate of Constantine the Great. A window into the elite Roman life of ancient Naissus through stunning floor mosaics.', 'Mediana (ancient Naissus) was the luxurious suburban estate of Emperor Constantine the Great, built at the turn of the 4th century. The site is a masterclass in Roman administrative luxury, featuring a massive Peristyle villa with 1,000 square meters of floor mosaics, including the famous "Geometric" and "God of the River" patterns. It provides a visual narrative of the Edict of Milan (313 AD) era, when the region was a core geopolitical pillar of the Empire. Following a major renovation, it now offers a world-class, intellectually rich archaeological experience.', 'Mediana (ancient Naissus) was the luxurious suburban estate of Emperor Constantine the Great, built at the turn of the 4th century. The site is a masterclass in Roman administrative luxury, featuring a massive Peristyle villa with 1,000 square meters of floor mosaics, including the famous "Geometric" and "God of the River" patterns. It provides a visual narrative of the Edict of Milan (313 AD) era, when the region was a core geopolitical pillar of the Empire. Following a major renovation, it now offers a world-class, intellectually rich archaeological experience.', '/src/assets/images/mediana_roman_villa_1778845820866.png', '1 - 2 hours', '3 hours', 180, 'Niš Outskirts', 'Niš Outskirts', '€3 - €8', 'Car / Taxi from Niš', 43.3106, 21.9422, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('54', 'Temple of Saint Sava', 'Temple of Saint Sava', 'History', 'One of the world’s largest Orthodox churches and a powerful symbol of modern Serbian identity. Featuring breathtaking golden mosaics.', 'One of the world’s largest Orthodox churches and a powerful symbol of modern Serbian identity. Featuring breathtaking golden mosaics.', 'The Temple of Saint Sava is one of the world''s largest Orthodox structures, with a central dome reaching 70 meters in height. Its recently completed interior mosaics, designed by Nikolay Mukhin, cover 15,000 square meters—one of the largest mosaic projects in Christian history. The lower level houses the "Crypto-Temple," a masterpiece of marble and gold leaf. It is a monumental expression of Serbo-Byzantine revivalism and national resilience, representing the city’s spiritual heart and a triumph of modern artistic craftsmanship.', 'The Temple of Saint Sava is one of the world''s largest Orthodox structures, with a central dome reaching 70 meters in height. Its recently completed interior mosaics, designed by Nikolay Mukhin, cover 15,000 square meters—one of the largest mosaic projects in Christian history. The lower level houses the "Crypto-Temple," a masterpiece of marble and gold leaf. It is a monumental expression of Serbo-Byzantine revivalism and national resilience, representing the city’s spiritual heart and a triumph of modern artistic craftsmanship.', '/src/assets/images/saint_sava_temple_interior_1778845911761.png', '1 - 3 hours', 'Urban access', 10, 'Vračar, Belgrade', 'Vračar, Belgrade', 'Free / Donation', 'On Foot / Taxi', 44.7981, 20.4678, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('56', 'Oplenac & Royal Mausoleum', 'Oplenac & Royal Mausoleum', 'History', 'The dynastic heart of modern Serbia. A stunning hilltop church featuring one of Europe’s most elaborate mosaic interiors reproducing medieval frescoes.', 'The dynastic heart of modern Serbia. A stunning hilltop church featuring one of Europe’s most elaborate mosaic interiors reproducing medieval frescoes.', 'Oplenac is the royal foundation of King Peter I Karađorđević (1844–1921), featuring the Church of Saint George and the Royal Mausoleum. The church interior is a mosaic marvel, containing 725 compositions and over 1,500 individual figures, meticulously copying the most important medieval frescoes from monasteries like Studenica and Mileševa. Over 40 million mosaic pieces in 15,000 shades of glass were used. It is a physical archive of Serbian medieval art, presented within a stunning Early 20th-century royal parkland, making it a high-status cultural pilgrimage.', 'Oplenac is the royal foundation of King Peter I Karađorđević (1844–1921), featuring the Church of Saint George and the Royal Mausoleum. The church interior is a mosaic marvel, containing 725 compositions and over 1,500 individual figures, meticulously copying the most important medieval frescoes from monasteries like Studenica and Mileševa. Over 40 million mosaic pieces in 15,000 shades of glass were used. It is a physical archive of Serbian medieval art, presented within a stunning Early 20th-century royal parkland, making it a high-status cultural pilgrimage.', '/src/assets/images/oplenac_mausoleum_mosaics_1778846378714.png', '2 - 4 hours', '1.5 hours', 90, 'Topola, Central Serbia', 'Topola, Central Serbia', '€5 - €15', 'Car / Private Tour', 44.2467, 20.6841, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('67', 'Pirot Kilim (Kilim) Workshop', 'Pirot Kilim (Kilim) Workshop', 'History, Travel', 'UNESCO-recognized hand-woven carpets with geometric symbolism. A geometric masterpiece of Balkan textile art.', 'UNESCO-recognized hand-woven carpets with geometric symbolism. A geometric masterpiece of Balkan textile art.', 'The Pirot Kilim is a UNESCO-nominated masterpiece of two-sided geometric weaving, featuring 95 specific patterns and 122 ornaments. Crafted at the "Damsko srce" (Lady''s Heart) workshop and others, these carpets utilize local mountain wool and natural dyes. Historically presented as diplomatic gifts to kings and czars, each pattern (like the "Mirror of the Soul" or "The Lizard") carries deep symbolic and ancestral protection. It is the most significant textile treasure of the Balkan region, representing a high-status cultural object that visually rivals the world’s finest modernist art.', 'The Pirot Kilim is a UNESCO-nominated masterpiece of two-sided geometric weaving, featuring 95 specific patterns and 122 ornaments. Crafted at the "Damsko srce" (Lady''s Heart) workshop and others, these carpets utilize local mountain wool and natural dyes. Historically presented as diplomatic gifts to kings and czars, each pattern (like the "Mirror of the Soul" or "The Lizard") carries deep symbolic and ancestral protection. It is the most significant textile treasure of the Balkan region, representing a high-status cultural object that visually rivals the world’s finest modernist art.', '/src/assets/images/pirot_kilim_weaving_craft_1778847353764.png', '2 hours (workshop visit)', '3.5 hours', 210, 'Pirot, SE Serbia', 'Pirot, SE Serbia', '€150 - €2000+', 'Car', 43.1556, 22.5858, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('9', 'Wines from the Sands', 'Vina sa peska (Palić)', 'Gastronomy, Travel', 'Discover mineral wines from the ancient Pannonian Sea floor. Unique terroir of sand and Art Nouveau wineries near the Hungarian border.', 'Otkrijte mineralna vina sa peskovitog dna nekadašnjeg Panonskog mora. Vinarija Zvonko Bogdan i čuveni palićki teroar.', 'In the far north, near the Hungarian border, the Subotica-Horgoš sands are the remains of the Pannonian Sea. This terrain defines "Wines from the Sands" (Vina sa peska), characterized by high minerality and refreshing acidity. The region is home to the indigenous "Kadarka" and "Kevedinka" varieties. Wineries like Vinarija Zvonko Bogdan (a Secessionist architectural masterpiece) represent the peak of North Serbian wine culture. For the connoisseur, it offers a sophisticated, mineral-driven alternative to the heavier reds of central Serbia, set amidst stunning Art Nouveau landscapes.', 'Na samom severu, blizu mađarske granice, Subotičko-horgoška peščara čuva ostatke drevnog Panonskog mora. Ovaj specifičan teroar rađa čuvena "Vina sa peska", prepoznatljiva po jedinstvenoj mineralnosti, laganoj slanoći i izuzetnoj svežini. Regija je dom autohtonih i odomaćenih sorti kao što su Kadarka i Kevedinka. Vinarija Zvonko Bogdan, remek-delo mađarske secesije, predstavlja vrhunski vinski i estetski doživljaj severne Srbije. Za poznavaoce i hedoniste, ova vinarija nudi prefinjenu i osvežavajuću paletu belih i crvenih vina poput legendarne kupaže "8 Tamburaša", uokvirena bajkovitim vinogradima pored jezera Palić.', '/src/assets/images/subotica_sand_wines_1778841182776.png', '4-6 hours', '2 hours', 120, 'Subotica / Palić', 'Subotica / Palić', '€20 - €50', 'Car / Bus', 46.1002, 19.6676, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('10', 'Rakia Bar Belgrade', 'Rakia Bar Belgrade', 'Gastronomy, Travel', 'The pioneer of modern rakia culture. Experience elevated rakia through sophisticated pairings and educational tastings.', 'The pioneer of modern rakia culture. Experience elevated rakia through sophisticated pairings and educational tastings.', 'Opened in 2003, Rakia Bar was a pioneering project in Belgrade''s Vračar district that redefined the national spirit from a daily peasant drink to a high-end gastronomic product. It offers over 50 varieties of Rakija (Šljiva, Viljamovka, Dunja, Kajsija) sourced from family-run distilleries throughout Šumadija and Eastern Serbia. Each serving is accompanied by a specifically paired "meze" (bite) designed to highlight the spirit''s mineral or fruity notes. It remains the essential starting point for an intellectually engaged introduction to the Balkan guest ritual and the art of fruit distillation.', 'Opened in 2003, Rakia Bar was a pioneering project in Belgrade''s Vračar district that redefined the national spirit from a daily peasant drink to a high-end gastronomic product. It offers over 50 varieties of Rakija (Šljiva, Viljamovka, Dunja, Kajsija) sourced from family-run distilleries throughout Šumadija and Eastern Serbia. Each serving is accompanied by a specifically paired "meze" (bite) designed to highlight the spirit''s mineral or fruity notes. It remains the essential starting point for an intellectually engaged introduction to the Balkan guest ritual and the art of fruit distillation.', '/src/assets/images/rakia_bar_interior_premium_1778841199447.png', '1-3 hours', '10 - 15 minutes', 15, 'Belgrade City Center', 'Belgrade City Center', '€15 - €40', 'Foot / Taxi', 44.8186, 20.4573, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('11', 'Distillery Zarić', 'Distillery Zarić', 'Gastronomy, Travel', 'One of the most awarded high-tech distilleries in the world, producing world-class spirits in the picturesque Kosjerić.', 'One of the most awarded high-tech distilleries in the world, producing world-class spirits in the picturesque Kosjerić.', 'Destilerija Zarić, located in the fruit-rich Kosjerić region, is a high-tech marvel built on the foundations of the historic "Povlen" distillery (founded 1946). It represents the modern peak of Serbian Rakija production, utilizing state-of-the-art distillation technology to create spirits like "Nirvana" (plum) and "Nostalgija" (quince), which have consistently won Grand Gold medals at the Brussels Spirits Selection. For the educated visitor, a tour here offers a masterclass in how traditional Balkan "terroir" can be translated into world-class luxury benchmarks.', 'Destilerija Zarić, located in the fruit-rich Kosjerić region, is a high-tech marvel built on the foundations of the historic "Povlen" distillery (founded 1946). It represents the modern peak of Serbian Rakija production, utilizing state-of-the-art distillation technology to create spirits like "Nirvana" (plum) and "Nostalgija" (quince), which have consistently won Grand Gold medals at the Brussels Spirits Selection. For the educated visitor, a tour here offers a masterclass in how traditional Balkan "terroir" can be translated into world-class luxury benchmarks.', '/src/assets/images/distillery_zaric_modern_1778841217471.png', '2-3 hours', '2.5 hours', 150, 'Kosjerić', 'Kosjerić', '€20 - €60', 'Car', 43.9958, 19.9142, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('25', 'Rajačke Pimnice', 'Rajačke Pimnice', 'Gastronomy, Travel', 'A unique wine heritage village featuring a dense complex of 18th-century stone cellars. Authentic, raw, and deeply cultural wine traditions in Eastern Serbia.', 'A unique wine heritage village featuring a dense complex of 18th-century stone cellars. Authentic, raw, and deeply cultural wine traditions in Eastern Serbia.', 'Rajačke Pimnice (or Pivnice) is a unique complex of over 270 stone wine cellars built between the mid-18th and early 20th centuries. These structures, carved from local sandstone and topped with oak, were built by villagers from Rajac specifically for wine aging. The nearby 18th-century cemetery features massive stone headstones with unique "Sun King" and solar motifs, suggesting a deep, almost mystical connection to the harvest. The region specializes in "Black Tamjanika" (Crna tamjanika), a rare muscat variety that offers an intellectually satisfying alternative to globalized wine styles.', 'Rajačke Pimnice (or Pivnice) is a unique complex of over 270 stone wine cellars built between the mid-18th and early 20th centuries. These structures, carved from local sandstone and topped with oak, were built by villagers from Rajac specifically for wine aging. The nearby 18th-century cemetery features massive stone headstones with unique "Sun King" and solar motifs, suggesting a deep, almost mystical connection to the harvest. The region specializes in "Black Tamjanika" (Crna tamjanika), a rare muscat variety that offers an intellectually satisfying alternative to globalized wine styles.', '/src/assets/images/rajacke_pimnice_village_1778843436699.png', 'Half day to overnight', '3.5 - 4 hours', 220, 'Near Negotin', 'Near Negotin', '€10 - €150', 'Car', 44.1167, 22.5667, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('27', 'Homa Restaurant', 'Homa Restaurant', 'Gastronomy', 'Belgrade’s pioneer of modern fine dining. A minimal and sophisticated space blending local ingredients with advanced culinary techniques.', 'Belgrade’s pioneer of modern fine dining. A minimal and sophisticated space blending local ingredients with advanced culinary techniques.', 'Homa is the intellectual flagship of Belgrade’s fine dining scene, led by Chef Filip Ćirić. Its minimalist, white-on-white aesthetic in the Dorćol district allows the focus to remain strictly on the 8 or 12-course tasting menus. The cuisine is "Balkan-Technical," utilizing local terroir—such as Mangalica pork or forest truffles—processed through modern European culinary logic. It was one of the first Serbian restaurants to be recommended by the Michelin Guide, serving as a sophisticated benchmark for the city’s contemporary creative identity.', 'Homa is the intellectual flagship of Belgrade’s fine dining scene, led by Chef Filip Ćirić. Its minimalist, white-on-white aesthetic in the Dorćol district allows the focus to remain strictly on the 8 or 12-course tasting menus. The cuisine is "Balkan-Technical," utilizing local terroir—such as Mangalica pork or forest truffles—processed through modern European culinary logic. It was one of the first Serbian restaurants to be recommended by the Michelin Guide, serving as a sophisticated benchmark for the city’s contemporary creative identity.', '/src/assets/images/homa_restaurant_interior_1778843469455.png', '2 - 3 hours', 'Urban access', 20, 'Dorćol, Belgrade', 'Dorćol, Belgrade', '€60 - €140 per person', 'Taxi / On Foot', 44.8252, 20.4638, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('29', 'Kalemegdanska Terasa', 'Kalemegdanska Terasa', 'Gastronomy', 'The essential Belgrade experience. Sunset dining and jazz within the layers of the historic Belgrade Fortress, overlooking the legendary river confluence.', 'The essential Belgrade experience. Sunset dining and jazz within the layers of the historic Belgrade Fortress, overlooking the legendary river confluence.', 'Kalemegdanska Terasa is situated within the 15th-century "Zindan" (Dungeon) Gate area of the Belgrade Fortress. For decades, it has served as the city''s high-society meeting point, blending French-inspired fine dining with views of the Big War Island and the river confluence. At sunset, the transition into live jazz creates an atmosphere of "Interwar Belgrade" elegance. For the sophisticated traveler, dining here is a ritual that connects the prehistoric beginnings of the city with its contemporary, high-performing urban elite.', 'Kalemegdanska Terasa is situated within the 15th-century "Zindan" (Dungeon) Gate area of the Belgrade Fortress. For decades, it has served as the city''s high-society meeting point, blending French-inspired fine dining with views of the Big War Island and the river confluence. At sunset, the transition into live jazz creates an atmosphere of "Interwar Belgrade" elegance. For the sophisticated traveler, dining here is a ritual that connects the prehistoric beginnings of the city with its contemporary, high-performing urban elite.', '/src/assets/images/kalemegdanska_terasa_sunset_1778843501085.png', 'Evening to full night', 'Urban access', 15, 'Kalemegdan, Belgrade', 'Kalemegdan, Belgrade', '€20 - €120', 'On Foot / Taxi', 44.8214, 20.4502, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('33', 'Tri Šešira (Three Hats)', 'Tri Šešira (Three Hats)', 'Gastronomy', 'One of Belgrade’s oldest and most recognizable traditional restaurants. Located in the bohemian Skadarlija district, it preserves 19th-century urban Serbian dining rituals.', 'One of Belgrade’s oldest and most recognizable traditional restaurants. Located in the bohemian Skadarlija district, it preserves 19th-century urban Serbian dining rituals.', 'Established in 1864, Tri Šešira (Three Hats) is the oldest restaurant in the Skadarlija bohemian district. It has hosted legends like Jimi Hendrix, George Bush, and Margaret Thatcher, yet it remains a sanctuary for "Old Belgrade" social rituals. The restaurant is famous for its slow-cooked Serbian stews (Čorba) and grilled specialties (Roštilj), served amidst live acoustic "Starogradska" music. It is an intellectually rewarding encounter with the city''s 19th-century soul, where the boundary between gastronomy and theater is elegantly blurred.', 'Established in 1864, Tri Šešira (Three Hats) is the oldest restaurant in the Skadarlija bohemian district. It has hosted legends like Jimi Hendrix, George Bush, and Margaret Thatcher, yet it remains a sanctuary for "Old Belgrade" social rituals. The restaurant is famous for its slow-cooked Serbian stews (Čorba) and grilled specialties (Roštilj), served amidst live acoustic "Starogradska" music. It is an intellectually rewarding encounter with the city''s 19th-century soul, where the boundary between gastronomy and theater is elegantly blurred.', '/src/assets/images/tri_sesira_skadarlija_1778843981314.png', '2 - 4 hours', 'Urban access', 15, 'Skadarlija, Belgrade', 'Skadarlija, Belgrade', '€30 - €90', 'On Foot / Taxi', 44.8175, 20.4628, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('37', 'Ambar Restaurant', 'Ambar Restaurant', 'Gastronomy', 'Modern Balkan small-plate dining on the Sava riverfront. A sophisticated and international introduction to regional flavors, from kajmak to creative kebabs.', 'Modern Balkan small-plate dining on the Sava riverfront. A sophisticated and international introduction to regional flavors, from kajmak to creative kebabs.', 'Ambar, located in the historic Beton Hala red-brick warehouses, is the award-winning "Balkan Tapas" concept from the Street Guys Hospitality group. It reimagines Serbian flavors—like AJvar, Kajmak, and Urnebes—into a sophisticated small-plate format designed for sharing. The menu is an intellectually rich tour of several regional terroirs, complemented by an extensive list of boutique Serbian wines and over 40 types of premium Rakija. It is the definitive venue for the modern, cosmopolitan traveler seeking an authentic yet polished encounter with Balkan soul.', 'Ambar, located in the historic Beton Hala red-brick warehouses, is the award-winning "Balkan Tapas" concept from the Street Guys Hospitality group. It reimagines Serbian flavors—like AJvar, Kajmak, and Urnebes—into a sophisticated small-plate format designed for sharing. The menu is an intellectually rich tour of several regional terroirs, complemented by an extensive list of boutique Serbian wines and over 40 types of premium Rakija. It is the definitive venue for the modern, cosmopolitan traveler seeking an authentic yet polished encounter with Balkan soul.', '/src/assets/images/ambar_belgrade_riverfront_1778844046663.png', '2 - 3 hours', 'Urban access', 15, 'Beton Hala, Belgrade', 'Beton Hala, Belgrade', '€35 - €100', 'Taxi / On Foot', 44.8182, 20.4491, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('42', 'Salon 1905', 'Salon 1905', 'Gastronomy', 'A grand fine-dining experience within the historic Geozavod building. Combining royal Yugoslav aesthetics with formal European culinary techniques.', 'A grand fine-dining experience within the historic Geozavod building. Combining royal Yugoslav aesthetics with formal European culinary techniques.', 'Salon 1905 is housed in the "Beogradska Zadruga" (Geozavod) building, a 1907-1910 masterpiece of Art Nouveau and Academicism designed by Nikola Nestorović and Andra Stevanović. The restaurant’s interior—a cathedral of marble, bronze, and gold leaf—is considered the most opulent in the Balkans. Its culinary philosophy matches the architectural grandeur, blending local organic ingredients with formal European techniques. For the sophisticated traveler, dining here is an immersive historical performance, reflecting the Belle Époque confidence of early 20th-century Belgrade.', 'Salon 1905 is housed in the "Beogradska Zadruga" (Geozavod) building, a 1907-1910 masterpiece of Art Nouveau and Academicism designed by Nikola Nestorović and Andra Stevanović. The restaurant’s interior—a cathedral of marble, bronze, and gold leaf—is considered the most opulent in the Balkans. Its culinary philosophy matches the architectural grandeur, blending local organic ingredients with formal European techniques. For the sophisticated traveler, dining here is an immersive historical performance, reflecting the Belle Époque confidence of early 20th-century Belgrade.', '/src/assets/images/salon_1905_interior_1778845083168.png', '2 - 4 hours', 'Urban access', 10, 'Savamala, Belgrade', 'Savamala, Belgrade', '€80 - €200 per person', 'Taxi / On Foot', 44.8142, 20.4508, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('47', 'Comunale Caffè e Cucina', 'Comunale Caffè e Cucina', 'Gastronomy', 'Belgrade’s contemporary cosmopolitan spirit on the riverfront. Mediterranean-inspired cuisine meets industrial chic design at Beton Hala.', 'Belgrade’s contemporary cosmopolitan spirit on the riverfront. Mediterranean-inspired cuisine meets industrial chic design at Beton Hala.', 'Comunale, located in the red-brick Beton Hala warehouses, is a pioneer of "Industrial Chic" on the Belgrade riverfront. Designed with long communal tables (hence the name), it fosters a social, Mediterranean-style dining ritual. The menu focuses on high-precision Italian and Adriatic flavors, from slow-fermented pizzas to fresh seafood. For the sophisticated traveler, it represents the successful regeneration of Belgrade’s port infrastructure into a world-class hospitality hub where the city’s business and creative elites converge at sunset.', 'Comunale, located in the red-brick Beton Hala warehouses, is a pioneer of "Industrial Chic" on the Belgrade riverfront. Designed with long communal tables (hence the name), it fosters a social, Mediterranean-style dining ritual. The menu focuses on high-precision Italian and Adriatic flavors, from slow-fermented pizzas to fresh seafood. For the sophisticated traveler, it represents the successful regeneration of Belgrade’s port infrastructure into a world-class hospitality hub where the city’s business and creative elites converge at sunset.', '/src/assets/images/comunale_beton_hala_1778845784310.png', '2 - 4 hours', 'Urban access', 15, 'Beton Hala, Belgrade', 'Beton Hala, Belgrade', '€30 - €120', 'Taxi / On Foot', 44.8182, 20.4491, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('52', 'Pirot Gastronomy', 'Pirot Gastronomy', 'Gastronomy', 'Deeply authentic mountain culinary traditions from Southeastern Serbia. Famous for aged cheeses, slow-cooked lamb, and the iconic Pirot Kilim culture.', 'Deeply authentic mountain culinary traditions from Southeastern Serbia. Famous for aged cheeses, slow-cooked lamb, and the iconic Pirot Kilim culture.', 'Pirot is home to the UNESCO-nominated "Pirot Kilim" (Pirotski ćilim), a geometric weaving tradition that has survived since the 16th century. The region’s gastronomy is equally legendary, defined by "Ironed Sausage" (Peglana kobasica) and "Kačkavalj" cheese, both protected by geographical origin labels. This pastoral culture is a pinnacle of "Balkan Terroir," where slow-produced ingredients and symbolic weaving patterns create a deeply consistent cultural identity. It is a must-visit for the "Educated Consumer" who values artisanal integrity and historical depth over mass production.', 'Pirot is home to the UNESCO-nominated "Pirot Kilim" (Pirotski ćilim), a geometric weaving tradition that has survived since the 16th century. The region’s gastronomy is equally legendary, defined by "Ironed Sausage" (Peglana kobasica) and "Kačkavalj" cheese, both protected by geographical origin labels. This pastoral culture is a pinnacle of "Balkan Terroir," where slow-produced ingredients and symbolic weaving patterns create a deeply consistent cultural identity. It is a must-visit for the "Educated Consumer" who values artisanal integrity and historical depth over mass production.', '/src/assets/images/pirot_gastronomy_cheese_1778845871088.png', '1 - 3 days', '3.5 hours', 210, 'Southeastern Serbia', 'Southeastern Serbia', '€40 - €160', 'Car / Train', 43.1556, 22.5858, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('58', 'Kafanas of Old Zemun', 'Kafanas of Old Zemun', 'Gastronomy, Clubbing', 'Authentic riverside dining culture in the charm of Old Zemun. Traditional fish restaurants, Austro-Hungarian architecture, and acoustic tamburica music.', 'Authentic riverside dining culture in the charm of Old Zemun. Traditional fish restaurants, Austro-Hungarian architecture, and acoustic tamburica music.', 'Old Zemun preserves a distinct Habsburg-Empire soul, officially becoming part of Belgrade only in 1934. Its riverside "Kafanas" along the Danube Quay are the custodians of "Starogradska" (Old Town) music and Danube fish stews (Riblja Čorba). The Landmark Gardoš Tower (The Millennium Tower, 1896) provides the iconic backdrop for sunset dinners. For the discerning traveler, Zemun offers an elegant, slow-paced authenticity where the sound of the tamburica and the slow flow of the river define the quintessential Central European-Balkan social experience.', 'Old Zemun preserves a distinct Habsburg-Empire soul, officially becoming part of Belgrade only in 1934. Its riverside "Kafanas" along the Danube Quay are the custodians of "Starogradska" (Old Town) music and Danube fish stews (Riblja Čorba). The Landmark Gardoš Tower (The Millennium Tower, 1896) provides the iconic backdrop for sunset dinners. For the discerning traveler, Zemun offers an elegant, slow-paced authenticity where the sound of the tamburica and the slow flow of the river define the quintessential Central European-Balkan social experience.', '/src/assets/images/zemun_danube_kafana_1778846414640.png', 'Afternoon to evening', 'Urban access', 20, 'Zemun, Belgrade', 'Zemun, Belgrade', '€25 - €120', 'Taxi / On Foot', 44.8436, 20.4136, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('63', 'Boutique Rakija Distilleries', 'Boutique Rakija Distilleries', 'Gastronomy', 'A journey through Serbia’s artisanal brandy movement. Discover family-run distilleries focusing on terroir-driven plum, quince, and apricot rakijas.', 'A journey through Serbia’s artisanal brandy movement. Discover family-run distilleries focusing on terroir-driven plum, quince, and apricot rakijas.', 'The "Boutique Rakija" movement is the Balkan equivalent of the Single Malt Scotch industry, featuring family-run distilleries like "Hubert" and "Tok" that prioritize terroir over volume. These producers utilize specific fruit varieties—such as the Crvena Ranka plum or the Williams pear—aged in Serbian "Hrast" (Oak) to achieve mineral and vanilla complexity. For the educated connoisseur, a tour of these cellars in regions like Šumadija or West Serbia provides an intellectually rich encounter with the "Alchemy of Fruit" and the sophisticated rituals of Balkan hospitality.', 'The "Boutique Rakija" movement is the Balkan equivalent of the Single Malt Scotch industry, featuring family-run distilleries like "Hubert" and "Tok" that prioritize terroir over volume. These producers utilize specific fruit varieties—such as the Crvena Ranka plum or the Williams pear—aged in Serbian "Hrast" (Oak) to achieve mineral and vanilla complexity. For the educated connoisseur, a tour of these cellars in regions like Šumadija or West Serbia provides an intellectually rich encounter with the "Alchemy of Fruit" and the sophisticated rituals of Balkan hospitality.', '/src/assets/images/serbian_boutique_distillery_rakija_1778846500524.png', 'Half day to weekend', 'Varies', 120, 'Multiple Regions', 'Multiple Regions', '€15 - €100+', 'Private Driver / Car', 44.2511, 20.6826, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('70', 'Guča Trumpet Festival Grounds', 'Guča Trumpet Festival Grounds', 'Gastronomy, Travel, History', 'The world’s largest gathering of brass bands. A raw, high-energy explosion of Balkan soul and brass virtuosity.', 'The world’s largest gathering of brass bands. A raw, high-energy explosion of Balkan soul and brass virtuosity.', 'Guča is more than a festival; it is the unofficial global capital of the "Southern Brass" sound (Balkanski trubači). Originating from 19th-century military traditions, the music at Guča transformed into a high-energy, emotionally complex Roma-influenced virtuosity. The festival, which attracts over 500,000 visitors annually, is a visceral, UNESCO-registered explosion of Balkan soul. For the educated traveler, Guča provides a rowdy, high-tempo masterclass in the resiliency and acoustic power of the region, where the trumpet is the primary vehicle for both history and hedonism.', 'Guča is more than a festival; it is the unofficial global capital of the "Southern Brass" sound (Balkanski trubači). Originating from 19th-century military traditions, the music at Guča transformed into a high-energy, emotionally complex Roma-influenced virtuosity. The festival, which attracts over 500,000 visitors annually, is a visceral, UNESCO-registered explosion of Balkan soul. For the educated traveler, Guča provides a rowdy, high-tempo masterclass in the resiliency and acoustic power of the region, where the trumpet is the primary vehicle for both history and hedonism.', '/src/assets/images/guca_trumpet_festival_spirit_1778847458509.png', 'Full day to 3 days', '2.5 - 3 hours', 160, 'Guča, SW Serbia', 'Guča, SW Serbia', 'Free - €100+', 'Car', 43.7761, 20.2317, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('72', 'Vojvodina Salaš (Ethno-Farms)', 'Vojvodina Salaš (Ethno-Farms)', 'Gastronomy', 'The ultimate "Slow Food" experience in the Pannonian Plains. Multi-hour dining rituals in historic 19th-century farmsteads.', 'The ultimate "Slow Food" experience in the Pannonian Plains. Multi-hour dining rituals in historic 19th-century farmsteads.', 'The "Salaš" (Ethno-Farmstead) is the spiritual and gastronomic backbone of Vojvodina, with institutions like Salaš 137 in Turija preserving the 19th-century Pannonian rural lifestyle. These farmsteads are the core of the "Slow Food" movement, where multi-hour dining rituals feature slow-roasted duck with poppy seeds, homemade "Štrudla," and high-quality local wines. Accompanied by the acoustic "Tamburica" bands, the Salaš experience is an intellectually satisfying retreat into a world defined by the slow, seasonal rhythms of the northern plains, far from urban density.', 'The "Salaš" (Ethno-Farmstead) is the spiritual and gastronomic backbone of Vojvodina, with institutions like Salaš 137 in Turija preserving the 19th-century Pannonian rural lifestyle. These farmsteads are the core of the "Slow Food" movement, where multi-hour dining rituals feature slow-roasted duck with poppy seeds, homemade "Štrudla," and high-quality local wines. Accompanied by the acoustic "Tamburica" bands, the Salaš experience is an intellectually satisfying retreat into a world defined by the slow, seasonal rhythms of the northern plains, far from urban density.', '/src/assets/images/salas_ethno_farm_food_1778847386244.png', '4 - 6 hours', '1 - 2 hours', 90, 'Various / Near Novi Sad', 'Various / Near Novi Sad', '€25 - €60 per person', 'Car', 45.3622, 19.8406, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('101', 'Nišville Jazz Festival', 'Nišville džez festival', 'Gastronomy', 'Sophisticated live jazz meets the finest Southern Serbian cuisine and wines inside an Ottoman-era fortress.', 'Sofisticirani džez festival u drevnoj Niškoj tvrđavi, sa naglaskom na gastronomiju i i vrhunska vina.', 'Nišville Jazz Festival is a sublime cultural event combining high-level global jazz performances with the rich, spice-driven gastronomy and wine-making culture of Southern Serbia. Hosted inside the grand stone battlements of the Ottoman Niš Fortress, it provides a highly relaxed, elite dinner and concert atmosphere. Under warm yellow lanterns, senior business leaders and cultural travelers gather to discuss ideas and savor premium regional vintages, offering an unhurried, memorable, and sensory-rich evening.', 'Nišville spaja tradicionalni džez stil sa zvucima Balkana u fascinantnom ambijentu turske tvrđave u Nišu. To je prefinjen i zreo kulturni događaj koji akcenat stavlja i na gurmanski identitet srpskog juga, uz degustacije vina i autentičnih pikantnih jela. Izvanredno za poslovne lidere i starije profesionalce koji traže akustički i istorijski spektakl, južnjačku toplinu i vrhunski gastronomski merak.', '/src/assets/images/nisville_jazz_1779796319989.png', '1 - 2 nights', '2.5 hours', 150, 'Niš Fortress', 'Niš', '€30 - €120', 'Car / Highway Express Bus', 43.3249, 21.8953, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('6', 'Sremski Karlovci', 'Sremski Karlovci', 'Travel, History', 'Serbia’s most refined baroque town and the spiritual heart of its culture. Known for unique Bermet wine, once an imperial favorite, and stunning Austro-Hungarian architecture.', 'Serbia’s most refined baroque town and the spiritual heart of its culture. Known for unique Bermet wine, once an imperial favorite, and stunning Austro-Hungarian architecture.', 'Sremski Karlovci is a museum-town reflecting the baroque elegance of the 18th and 19th centuries. As the spiritual seat of the Serbian Orthodox Church in the Habsburg Empire, it hosted the historic Treaty of Karlowitz in 1699. Significant landmarks include the Patriarchate Court (1892), Saint Nicholas Cathedral, and the first Serbian Gymnasium (founded 1791). The town is legendary for "Bermet," a dessert wine with over 20 herbs and spices, once served on the Titanic and at the Austrian imperial court. It is a refined destination for those who appreciate the intersection of high culture, religion, and viticulture.', 'Sremski Karlovci is a museum-town reflecting the baroque elegance of the 18th and 19th centuries. As the spiritual seat of the Serbian Orthodox Church in the Habsburg Empire, it hosted the historic Treaty of Karlowitz in 1699. Significant landmarks include the Patriarchate Court (1892), Saint Nicholas Cathedral, and the first Serbian Gymnasium (founded 1791). The town is legendary for "Bermet," a dessert wine with over 20 herbs and spices, once served on the Titanic and at the Austrian imperial court. It is a refined destination for those who appreciate the intersection of high culture, religion, and viticulture.', '/src/assets/images/sremski_karlovci_town_1778841131222.png', 'Half day to overnight', '1 hour', 60, 'Near Novi Sad', 'Near Novi Sad', '€10 - €80', 'Car / Train', 45.2023, 19.9324, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('8', 'Zlakusa Pottery Village', 'Zlakusa Pottery Village', 'Travel', 'Experience a 400-year-old pottery technique combining clay and calcite, fired in open flames. UNESCO-recognized intangible heritage.', 'Experience a 400-year-old pottery technique combining clay and calcite, fired in open flames. UNESCO-recognized intangible heritage.', 'The village of Zlakusa preserves a unique pottery technique (Lončarstvo) that has remained unchanged for four centuries and is now UNESCO-registered. Unlike standard pottery, Zlakusa artisans blend local clay with "vrsta"—a specific type of powdered calcite mineral. The vessels are shaped on a slow wooden wheel and fired in an open pit at 600-700°C. This ancient method results in pots that are exceptionally resistant to heat, making them essential for "Slow Food" cooking. It is a living laboratory of Balkan Neolithic technology perfectly adapted for modern high-end gastronomy.', 'The village of Zlakusa preserves a unique pottery technique (Lončarstvo) that has remained unchanged for four centuries and is now UNESCO-registered. Unlike standard pottery, Zlakusa artisans blend local clay with "vrsta"—a specific type of powdered calcite mineral. The vessels are shaped on a slow wooden wheel and fired in an open pit at 600-700°C. This ancient method results in pots that are exceptionally resistant to heat, making them essential for "Slow Food" cooking. It is a living laboratory of Balkan Neolithic technology perfectly adapted for modern high-end gastronomy.', '/src/assets/images/zlakusa_pottery_craft_1778841163739.png', '2-3 hours', '3 hours', 180, 'Zlakusa, Užice', 'Zlakusa, Užice', '€10 - €30', 'Car', 43.8118, 19.9318, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('21', 'Fruška Gora', 'Fruška Gora', 'Travel', 'Vojvodina’s "Holy Mountain" blends forest wellness with 16 Orthodox monasteries and premium wineries. A refined escape for forest hiking and slow rural gastronomy.', 'Vojvodina’s "Holy Mountain" blends forest wellness with 16 Orthodox monasteries and premium wineries. A refined escape for forest hiking and slow rural gastronomy.', 'Fruška Gora is a cultural and natural sanctuary in northern Serbia. Known for its monasteries that preserved Serbian identity during Ottoman rule, it is today a destination for understated luxury. Visitors can enjoy boutique wineries, forest hiking trails, and monastery honey. It is particularly suited for 1-3 day retreats for those seeking tranquility, herbal traditions, and sophisticated forest wellness.', 'Fruška Gora is a cultural and natural sanctuary in northern Serbia. Known for its monasteries that preserved Serbian identity during Ottoman rule, it is today a destination for understated luxury. Visitors can enjoy boutique wineries, forest hiking trails, and monastery honey. It is particularly suited for 1-3 day retreats for those seeking tranquility, herbal traditions, and sophisticated forest wellness.', '/src/assets/images/fruska_gora_monastery_vineyard_1778842911981.png', 'Day trip to weekend', '1 - 1.5 hours', 75, 'Fruška Gora National Park', 'Fruška Gora National Park', '€15 - €250', 'Car', 45.15, 19.85, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('22', 'Mokra Gora', 'Mokra Gora', 'Travel', 'Serbia’s most cinematic mountain experience, home to the legendary Šargan Eight heritage railway and traditional wooden architecture.', 'Serbia’s most cinematic mountain experience, home to the legendary Šargan Eight heritage railway and traditional wooden architecture.', 'Mokra Gora is a nostalgic journey through the Balkan mountains. The centerpiece is the Šargan Eight railway, an engineering feat that loops through tunnels and dramatic landscapes. Associated with filmmaker Emir Kusturica, the region blends mountain culture with Yugoslav industrial heritage, offering a high-quality retreat in a uniquely aesthetic wooden village (Drvenburg).', 'Mokra Gora is a nostalgic journey through the Balkan mountains. The centerpiece is the Šargan Eight railway, an engineering feat that loops through tunnels and dramatic landscapes. Associated with filmmaker Emir Kusturica, the region blends mountain culture with Yugoslav industrial heritage, offering a high-quality retreat in a uniquely aesthetic wooden village (Drvenburg).', '/src/assets/images/mokra_gora_sargan_eight_1778842930420.png', 'Full day to 2 days', '3.5 - 4 hours', 220, 'Zlatibor District', 'Zlatibor District', '€10 - €300', 'Car / Heritage Train', 43.8333, 19.5167, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('30', 'Drvengrad (Küstendorf)', 'Drvengrad (Küstendorf)', 'Travel', 'An artistic wooden mountain village created by filmmaker Emir Kusturica. A cinematic blend of traditional architecture, nostalgia, and mountain culture.', 'An artistic wooden mountain village created by filmmaker Emir Kusturica. A cinematic blend of traditional architecture, nostalgia, and mountain culture.', 'Drvengrad, also known as Küstendorf, is a total-artwork (Gesamtkunstwerk) created by filmmaker Emir Kusturica for his 2004 film "Life is a Miracle." Located on Mećavnik hill, all of its wooden structures—including the Church of St. Sava and the cinema boutique—were salvaged from original rural buildings. The village promotes a "Hand-Made Cinema" philosophy and hosts global stars at its annual festival. For the educated visitor, it offers a visceral, highly aestheticized encounter with Balkan rural memory, mountain biodiversity, and the cinematic imagination.', 'Drvengrad, also known as Küstendorf, is a total-artwork (Gesamtkunstwerk) created by filmmaker Emir Kusturica for his 2004 film "Life is a Miracle." Located on Mećavnik hill, all of its wooden structures—including the Church of St. Sava and the cinema boutique—were salvaged from original rural buildings. The village promotes a "Hand-Made Cinema" philosophy and hosts global stars at its annual festival. For the educated visitor, it offers a visceral, highly aestheticized encounter with Balkan rural memory, mountain biodiversity, and the cinematic imagination.', '/src/assets/images/drvengrad_wooden_village_1778843518053.png', '2 - 5 hours', '4 hours', 240, 'Mokra Gora', 'Mokra Gora', '€5 - €250', 'Car', 43.8333, 19.5167, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('34', 'Subotica & Palić', 'Subotica & Palić', 'Travel', 'A refined Austro-Hungarian cultural enclave featuring stunning Hungarian Secessionist architecture and a historic lakeside resort with an Olympic heritage.', 'A refined Austro-Hungarian cultural enclave featuring stunning Hungarian Secessionist architecture and a historic lakeside resort with an Olympic heritage.', 'Subotica is the European capital of Hungarian Secessionist (Art Nouveau) architecture, headlined by the Raichle Palace (1904) and the City Hall. Nearby Palić Lake was a sophisticated Austro-Hungarian resort that hosted the Palić Sports Games in 1880—predating the modern Olympics. The region is defined by the unique "Zsolnay" ceramics that decorate its landmarks and the mineral "Wines from the Sands." For the educated traveler, it offers a sophisticated, multi-ethnic cultural narrative that feels closer to Central Europe than the Pannonian interior.', 'Subotica is the European capital of Hungarian Secessionist (Art Nouveau) architecture, headlined by the Raichle Palace (1904) and the City Hall. Nearby Palić Lake was a sophisticated Austro-Hungarian resort that hosted the Palić Sports Games in 1880—predating the modern Olympics. The region is defined by the unique "Zsolnay" ceramics that decorate its landmarks and the mineral "Wines from the Sands." For the educated traveler, it offers a sophisticated, multi-ethnic cultural narrative that feels closer to Central Europe than the Pannonian interior.', '/src/assets/images/subotica_palic_lake_villa_1778843996440.png', 'Weekend to 3 days', '2.5 - 3 hours', 160, 'Northern Vojvodina', 'Northern Vojvodina', '€70 - €220', 'Car / Train', 46.1002, 19.6676, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('50', 'Divčibare Air Spa', 'Divčibare Air Spa', 'Travel, Wellbeing', 'A peaceful mountain-air retreat in western Serbia. Known for its restorative pine forests and understated wellness escapes.', 'A peaceful mountain-air retreat in western Serbia. Known for its restorative pine forests and understated wellness escapes.', 'Divčibare, a Plateau on Mount Maljen, has been an official "Air Spa" since 1932, recognized for its beneficial impact on the neurovegetative and respiratory systems. At 980 meters, it enjoys a unique microclimate where Mediterranean and continental air currents collide. Historically a retreat for the Belgrade intelligentsia, it maintains a quiet, understated atmosphere defined by pine forest "Forest Bathing" and gentle hiking trails like Crni Vrh. It is a sophisticated, low-density alternative for those seeking environmental restorative health without the noise of major ski resorts.', 'Divčibare, a Plateau on Mount Maljen, has been an official "Air Spa" since 1932, recognized for its beneficial impact on the neurovegetative and respiratory systems. At 980 meters, it enjoys a unique microclimate where Mediterranean and continental air currents collide. Historically a retreat for the Belgrade intelligentsia, it maintains a quiet, understated atmosphere defined by pine forest "Forest Bathing" and gentle hiking trails like Crni Vrh. It is a sophisticated, low-density alternative for those seeking environmental restorative health without the noise of major ski resorts.', '/src/assets/images/divcibare_pine_forest_1778845837560.png', 'Weekend to 4 days', '2 hours', 120, 'Western Serbia', 'Western Serbia', '€50 - €180', 'Car', 44.1114, 19.9886, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('55', 'Wine Routes of Šumadija', 'Wine Routes of Šumadija', 'Travel, Gastronomy', 'Serbia’s most ambitious modern wine region. Rolling hills, boutique wineries, and a revival of indigenous columns heritage.', 'Serbia’s most ambitious modern wine region. Rolling hills, boutique wineries, and a revival of indigenous columns heritage.', 'Šumadija, often called the "Serbian Tuscany," is the focus of a sophisticated wine renaissance. Modern wineries like "Aleksandrović" and "Radovanović" have successfully revived royal wine traditions from the 1920s Oplenac cellars. The region specializes in Sauvignon Blanc, Riesling, and the indigenous "Prokupac," thriving on the rolling limestone hills of Central Serbia. A wine route here combines high-end tastings with the political and royal history of the Karađorđević dynasty, offering an intellectually rich narrative of national and gastronomic revival.', 'Šumadija, often called the "Serbian Tuscany," is the focus of a sophisticated wine renaissance. Modern wineries like "Aleksandrović" and "Radovanović" have successfully revived royal wine traditions from the 1920s Oplenac cellars. The region specializes in Sauvignon Blanc, Riesling, and the indigenous "Prokupac," thriving on the rolling limestone hills of Central Serbia. A wine route here combines high-end tastings with the political and royal history of the Karađorđević dynasty, offering an intellectually rich narrative of national and gastronomic revival.', '/src/assets/images/sumadija_wine_route_1778845927893.png', 'Weekend to 3 days', '1 - 2 hours', 90, 'Central Serbia', 'Central Serbia', '€80 - €300', 'Private Driver / Car', 44.25, 20.5833, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('57', 'Kopaonik Mountain Resort', 'Kopaonik Mountain Resort', 'Travel', 'Serbia’s premier high-altitude resort. A year-round destination for skiing, hiking, and sophisticated luxury wellness in the "Mountain of the Sun."', 'Serbia’s premier high-altitude resort. A year-round destination for skiing, hiking, and sophisticated luxury wellness in the "Mountain of the Sun."', 'Kopaonik is Serbia''s "Mountain of the Sun," known for its sub-alpine microclimate and 160 sunshine days per year. It was a vital mining center in the Middle Ages (hence the name from "Kopati"—to dig) and now serves as the country''s premier high-altitude ski and wellness resort. The park protects endemic species like the Kopaonik houseleek and serves as an "Air Spa." For the international visitor, it offers a high-spec hospitality infrastructure (hotels like Viceroy and Gorski) that blends Alpine standards with a distinct Balkan social energy and high-end gastronomy.', 'Kopaonik is Serbia''s "Mountain of the Sun," known for its sub-alpine microclimate and 160 sunshine days per year. It was a vital mining center in the Middle Ages (hence the name from "Kopati"—to dig) and now serves as the country''s premier high-altitude ski and wellness resort. The park protects endemic species like the Kopaonik houseleek and serves as an "Air Spa." For the international visitor, it offers a high-spec hospitality infrastructure (hotels like Viceroy and Gorski) that blends Alpine standards with a distinct Balkan social energy and high-end gastronomy.', '/src/assets/images/kopaonik_mountain_winter_1778846397521.png', 'Weekend to 1 week', '4 hours', 240, 'Southern Serbia', 'Southern Serbia', '€80 - €500+ per night', 'Car / Private Transfer', 43.2833, 20.8167, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('59', 'Gostuša (The Stone Village)', 'Gostuša (The Stone Village)', 'Travel, History', 'An architectural marvel on Stara Planina. A village built entirely of stone, wood, and mud, preserving pre-industrial Balkan mountain life.', 'An architectural marvel on Stara Planina. A village built entirely of stone, wood, and mud, preserving pre-industrial Balkan mountain life.', 'Gostuša is a unique architectural preserve on the banks of Lake Zavoj, built entirely from hand-processed stone, wood, and clay—including the roofs (stone slabs). This "Vernacular Stone School" was recognized with a Europa Nostra Award for its preservation of pre-industrial building techniques. Traditionally a village of stone-cutters and shepherds, it offers a visceral, non-simulated experience of Balkan mountain survival. For the architecture specialist and photographer, Gostuša is an atmospheric masterpiece of "Ecological Honesty," untouched by modern cement or glass.', 'Gostuša is a unique architectural preserve on the banks of Lake Zavoj, built entirely from hand-processed stone, wood, and clay—including the roofs (stone slabs). This "Vernacular Stone School" was recognized with a Europa Nostra Award for its preservation of pre-industrial building techniques. Traditionally a village of stone-cutters and shepherds, it offers a visceral, non-simulated experience of Balkan mountain survival. For the architecture specialist and photographer, Gostuša is an atmospheric masterpiece of "Ecological Honesty," untouched by modern cement or glass.', '/src/assets/images/gostusa_stone_village_1778846432213.png', 'Half day to overnight', '4 hours', 240, 'Stara Planina Region', 'Stara Planina Region', '€20 - €120', 'Car', 43.15, 22.6833, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('64', 'Avala Tower & Mountain', 'Avala Tower & Mountain', 'Travel, Nature, History', 'The iconic panoramic viewpoint above Belgrade. A symbol of modern resilience and a gateway to the city’s layered historical memory.', 'The iconic panoramic viewpoint above Belgrade. A symbol of modern resilience and a gateway to the city’s layered historical memory.', 'Avala Tower is the architectural lighthouse of Belgrade, serving as the tallest structure in the Balkans at 204.68 meters. The original 1965 tower was destroyed in 1999 and triumphantly reconstructed in 2010 using over 5,000 tons of reinforced concrete. Nearby, the "Monument to the Unknown Hero"—a black marble mausoleum designed by Ivan Meštrović (1938)—reflects the city’s deep historical layeredness. For the sophisticated traveler, Avala offers a 360-degree topographical masterclass, stretching from the Danubian plains to the forested Šumadijan hills.', 'Avala Tower is the architectural lighthouse of Belgrade, serving as the tallest structure in the Balkans at 204.68 meters. The original 1965 tower was destroyed in 1999 and triumphantly reconstructed in 2010 using over 5,000 tons of reinforced concrete. Nearby, the "Monument to the Unknown Hero"—a black marble mausoleum designed by Ivan Meštrović (1938)—reflects the city’s deep historical layeredness. For the sophisticated traveler, Avala offers a 360-degree topographical masterclass, stretching from the Danubian plains to the forested Šumadijan hills.', '/src/assets/images/avala_tower_panoramic_view_1778846516735.png', 'Half day', '45 minutes', 45, 'Avala, Belgrade Outskirts', 'Avala, Belgrade Outskirts', '€3 - €8', 'Taxi / Car', 44.6908, 20.5144, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('65', 'EXPO 2027 Belgrade Complex', 'EXPO 2027 Belgrade Complex', 'Travel', 'The futuristic heart of EXPO 2027. A multi-functional complex designed for global dialogue on "Play for Humanity."', 'The futuristic heart of EXPO 2027. A multi-functional complex designed for global dialogue on "Play for Humanity."', 'The EXPO 2027 Belgrade Complex in Surčin is a 250,000-square-meter futuristic "Smart City" dedicated to the theme "Play for Humanity." Designed to be one of the world''s most sustainable event sites, it features the National Stadium and the centerpiece Expo pavilions that prioritize circular architecture and digital immersion. It serves as the global ground zero for discussing the future of resilience, technology, and social play. For the visitor, it is a visceral glimpse into "Serbia 2030," representing a high-performing, future-ready Belgrade integrated into the global innovation circuit.', 'The EXPO 2027 Belgrade Complex in Surčin is a 250,000-square-meter futuristic "Smart City" dedicated to the theme "Play for Humanity." Designed to be one of the world''s most sustainable event sites, it features the National Stadium and the centerpiece Expo pavilions that prioritize circular architecture and digital immersion. It serves as the global ground zero for discussing the future of resilience, technology, and social play. For the visitor, it is a visceral glimpse into "Serbia 2030," representing a high-performing, future-ready Belgrade integrated into the global innovation circuit.', '/src/assets/images/expo_2027_belgrade_future_1778847337979.png', 'Full day', '30-45 minutes', 45, 'Surčin, Belgrade', 'Surčin, Belgrade', 'Ticket dependent', 'EXPO Shuttle / Taxi', 44.8219, 20.2889, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('66', 'Sirogojno Hand-Knitted Wool', 'Sirogojno Hand-Knitted Wool', 'Travel, History', 'World-famous hand-knitted wool garments with regional motifs. A luxury heritage piece that once captured the Paris fashion runways.', 'World-famous hand-knitted wool garments with regional motifs. A luxury heritage piece that once captured the Paris fashion runways.', 'Sirogojno Style is the only Serbian fashion brand to have graced the runways of Paris, Rome, and New York in the 1970s. These hand-knitted wool garments, often featuring stylized Pannonian landscapes or floral motifs, are crafted by the "Sirogojno Women" using proprietary, high-softness wool processing. Each piece is a masterclass in "High-End Folk," representing a luxury sustainable heritage that bridge the gap between rural Balkan memory and international high fashion. For the collector, a Sirogojno piece is an intellectually valid, wearable investment in European artisanal excellence.', 'Sirogojno Style is the only Serbian fashion brand to have graced the runways of Paris, Rome, and New York in the 1970s. These hand-knitted wool garments, often featuring stylized Pannonian landscapes or floral motifs, are crafted by the "Sirogojno Women" using proprietary, high-softness wool processing. Each piece is a masterclass in "High-End Folk," representing a luxury sustainable heritage that bridge the gap between rural Balkan memory and international high fashion. For the collector, a Sirogojno piece is an intellectually valid, wearable investment in European artisanal excellence.', '/src/assets/images/sirogojno_knitted_wool_premium_1778847401094.png', '1 hour (shopping)', 'Varies (Belgrade shops or Zlatibor)', 20, 'Multiple / Sirogojno', 'Multiple / Sirogojno', '€80 - €350', 'On Foot / Car', 43.6872, 19.8805, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('68', 'Bitef Theatre & Festival', 'Bitef Theatre & Festival', 'Travel', 'Global epicenter of avant-garde theatre performance. Belgrade’s most intellectually daring cultural tradition since 1967.', 'Global epicenter of avant-garde theatre performance. Belgrade’s most intellectually daring cultural tradition since 1967.', 'BITEF (Belgrade International Theatre Festival), founded in 1967 by Mira Trailović and Jovan Ćirilov, is a cornerstone of global avant-garde performance. For decades, it has been the bridge where East met West during the Cold War, hosting figures like Peter Brook, Pina Bausch, and Robert Wilson. The Bitef Theatre, housed in a repurposed 1940s Protestant church in Dorćol, continues this "Permanent Revolution" year-round. For the culturally engaged traveler, Bitef offers an intellectually rigorous and often provocative experience of the modern Serbian creative soul at the peak of its global influence.', 'BITEF (Belgrade International Theatre Festival), founded in 1967 by Mira Trailović and Jovan Ćirilov, is a cornerstone of global avant-garde performance. For decades, it has been the bridge where East met West during the Cold War, hosting figures like Peter Brook, Pina Bausch, and Robert Wilson. The Bitef Theatre, housed in a repurposed 1940s Protestant church in Dorćol, continues this "Permanent Revolution" year-round. For the culturally engaged traveler, Bitef offers an intellectually rigorous and often provocative experience of the modern Serbian creative soul at the peak of its global influence.', '/src/assets/images/bitef_theatre_belgrade_modern_1778847369770.png', '2 - 3 hours', 'Urban access', 10, 'Dorćol, Belgrade', 'Dorćol, Belgrade', '€10 - €40', 'On Foot / Taxi', 44.8194, 20.4633, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('69', 'Serbian National Theatre (Novi Sad)', 'Serbian National Theatre (Novi Sad)', 'Travel', 'The oldest professional theatre among the Serbs. A grand brutalist landmark representing the "Serbian Athens."', 'The oldest professional theatre among the Serbs. A grand brutalist landmark representing the "Serbian Athens."', 'The Serbian National Theatre (SNP) in Novi Sad, established in 1861 by Dr. Jovan Đorđević, is the oldest professional theatre in the region. Its current Brutalist-Modernist temple of white marble (completed 1981) contains three stages and serves as the epicenter of the "Serbian Athens." The SNP is renowned for its high-spec Opera and Ballet productions, integrating 19th-century formal grandeur with contemporary stagecraft. For the sophisticated visitor, it represents the intellectual and artistic maturity of Vojvodina, offering a grand-scale experience of the Balkan performing arts.', 'The Serbian National Theatre (SNP) in Novi Sad, established in 1861 by Dr. Jovan Đorđević, is the oldest professional theatre in the region. Its current Brutalist-Modernist temple of white marble (completed 1981) contains three stages and serves as the epicenter of the "Serbian Athens." The SNP is renowned for its high-spec Opera and Ballet productions, integrating 19th-century formal grandeur with contemporary stagecraft. For the sophisticated visitor, it represents the intellectual and artistic maturity of Vojvodina, offering a grand-scale experience of the Balkan performing arts.', '/src/assets/images/national_theatre_novi_sad_1778847437149.png', '3 hours', '1 hour (Fast train)', 60, 'Novi Sad Square', 'Novi Sad Square', '€10 - €35', 'Train (Soko)', 45.255, 19.845, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('74', 'The Silk Thread Craft (Pančevo)', 'The Silk Thread Craft (Pančevo)', 'Travel', 'Preserving the rare Pannonian silk-weaving heritage. Hand-crafted textiles and accessories made with historical artisanal techniques.', 'Preserving the rare Pannonian silk-weaving heritage. Hand-crafted textiles and accessories made with historical artisanal techniques.', 'Pančevo was historically the primary silk-weaving hub of the Austro-Hungarian Empire, with the "Silk Thread" craft thriving under Empress Maria Theresa. Today, a few specialized workshops—like "Svilarska manufaktura"—preserve the delicate 18th-century art of silk thread work and hand-spinning. These pieces are rare, highly artisanal, and represent a fading Central European luxury tradition. For the visitor looking for a truly unique and lightweight souvenir, Pančevo silk work is a refined and intellectually rewarding choice, reflecting the city’s industrial and artisanal maturity.', 'Pančevo was historically the primary silk-weaving hub of the Austro-Hungarian Empire, with the "Silk Thread" craft thriving under Empress Maria Theresa. Today, a few specialized workshops—like "Svilarska manufaktura"—preserve the delicate 18th-century art of silk thread work and hand-spinning. These pieces are rare, highly artisanal, and represent a fading Central European luxury tradition. For the visitor looking for a truly unique and lightweight souvenir, Pančevo silk work is a refined and intellectually rewarding choice, reflecting the city’s industrial and artisanal maturity.', '/src/assets/images/pancevo_silk_thread_craft_1778847501434.png', '1 hour', '30 minutes', 30, 'Pančevo', 'Pančevo', '€30 - €200', 'Bus / Taxi', 44.8739, 20.6519, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('83', 'Đerdap Danube Cycling Segments', 'Đerdap Danube Cycling Segments', 'Travel, Nature', 'Moderate cycling segments passing Roman ruins, fortresses, and river viewpoints in Europe’s longest river canyon.', 'Moderate cycling segments passing Roman ruins, fortresses, and river viewpoints in Europe’s longest river canyon.', 'The Đerdap cycling segments follow the Danube through the "Iron Gates" (Gvozdena Kapija), Europe’s longest and deepest gorge. The route is a masterclass in monumental geography, passing the 14th-century Golubac Fortress and the 8,000-year-old Lepenski Vir settlement. Unlike the crowded sections of the Danube Cycle Path in Austria, the Serbian segments offer a visceral, raw encounter with the river’s power. It is an intellectually dense active-travel route where every turn reveals a new layer of the Roman and Byzantine frontier history.', 'The Đerdap cycling segments follow the Danube through the "Iron Gates" (Gvozdena Kapija), Europe’s longest and deepest gorge. The route is a masterclass in monumental geography, passing the 14th-century Golubac Fortress and the 8,000-year-old Lepenski Vir settlement. Unlike the crowded sections of the Danube Cycle Path in Austria, the Serbian segments offer a visceral, raw encounter with the river’s power. It is an intellectually dense active-travel route where every turn reveals a new layer of the Roman and Byzantine frontier history.', '/src/assets/images/djerdap_danube_cycling_1778848308378.png', '2 - 4 days', '3 hours', 180, 'Danube Corridor / Eastern Serbia', 'Danube Corridor / Eastern Serbia', '€80 - €280 per day', 'Car + Cycling segments', 44.6, 22.25, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('96', 'Belgrade Dance Festival', 'Beogradski festival igre', 'Travel', 'Witness leading contemporary dance companies from across the globe gather in Belgrade. A premium spring artistic spectacle during the EXPO 2027 window.', 'Izuzetan prolećni festival savremene igre koji okuplja svetske trupe u Beogradu.', 'The Belgrade Dance Festival has evolved into one of Europe’s most critical platforms for contemporary choreography and performance art. Showcasing world-class dance companies at the National Theatre and Sava Centar, it represents the ideal cultural companion for EXPO 2027 delegates. Emphasizing high-production standards, abstract aesthetics, and professional international networking, this springtime festival provides an elegant and intellectually stimulating evening of contemporary corporate hospitality.', 'Beogradski festival igre (Belgrade Dance Festival) postao je jedan od najvažnijih evropskih plesnih događaja. Tokom proleća, pod pokroviteljstvom EXPO 2027, festival okuplja najznačajnije svetske koreografe i prestižne plesne trupe u Narodnom pozorištu i Sava Centru. Savršen kulturni program za poslovne goste i diplomate koji cene savremenu estetiku, vrhunsku produkciju i kosmopolitsku atmosferu.', '/src/assets/images/belgrade_dance_festival_1779796215276.png', '2 - 3 hours', 'Urban access', 15, 'Belgrade', 'Beograd', '€20 - €100', 'Taxi / Walking', 44.8184, 20.4608, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('97', 'Mikser Festival', 'M6 Mikser Festival', 'Travel', 'Discover the intersection of urban design, architecture, and sustainable tech. Belgrade’s iconic, future-facing regional design movement.', 'Multidisciplinarni festival dizajna, arhitekture i kreativnih industrija prepoznat po startup energiji.', 'Mikser Festival is Southeast Europe’s largest regional exhibition of design, architectural planning, and green tech. Acting as a community-driven movement, it gathers designers, visionaries, and tech startups in Belgrade’s industrial silos. Perfect for EXPO 2027 business tourists, it explores the city’s thriving creative economy, micro-urban regeneration projects, and future-forward concepts for sustainable living in the Balkans.', 'Mikser Festival je najveća regionalna smotra kreativnosti, dizajna i održivog razvoja. Okuplja mlade talente, industrijske dizajnere i tech preduzetnike u postindustrijskom prostoru Silosa u Beogradu. Savršen za EXPO 2027 posetioce koji žele da istraže kreativni puls Balkana, inovativna rešenja u urbanizmu i novu startap zajednicu Srbije.', '/src/assets/images/mikser_festival_1779796233074.png', '1 day to weekend', 'Urban access', 15, 'Silosi Belgrade', 'Silosi Beograd', 'Free - €20', 'Taxi / CarGo', 44.8236, 20.4854, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('4', 'Vrnjačka Banja', 'Vrnjačka Banja', 'Wellbeing, Travel', 'The "Queen of Serbian Spas" combines Austro-Hungarian spa culture with Balkan thermal traditions. It maintains a functioning medical rehabilitation ecosystem since Roman times, with seven mineral springs and lush parklands.', 'Kraljica srpskih banja sa tradicijom još iz rimskih vremena i sedam mineralnih izvora.', 'Known since Roman times as "Aquae Orcinae," Vrnjačka Banja is the most celebrated of Serbia''s mineral spas. It flourished in the 19th century under the patronage of Prince Miloš Obrenović and later the Karađorđević dynasty, reflecting an Austro-Hungarian "Kurgarten" elegance. The town features seven mineral springs, including Toplovič (the only one at human body temperature, 36.5°C). Landmarks like the Bridge of Love (Most ljubavi), where the tradition of padlocks allegedly began during WWI, add a layer of romantic folklore. Today, it combines specialized rehabilitation centers like "Merkur" with sophisticated Japanese gardens and expansive parks, maintaining its status as the "Queen of Serbian Spas."', 'Vrnjačka Banja je najpoznatije banjsko mesto u Srbiji, sa tradicijom lečenja koja datira još od vremena cara Konstantina. Pored lekovitih izvora, nudi luksuzne wellness centre i prelepe parkove idealne za šetnju. Čuvena je i po ''Mostu ljubavi'' gde je tradicija zaključavanja katanaca i počela.', '/src/assets/images/vrnjacka_banja_1778841098566.png', 'Weekend to 1 week', '2.5 - 3 hours', 160, 'Central Serbia', 'Vrnjačka Banja', '€15 - €800+', 'Car / Train', 43.6214, 20.8924, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('28', 'Rtanj Mountain & Sokobanja', 'Rtanj Mountain & Sokobanja', 'Wellbeing', 'A blend of thermal recovery in Sokobanja and the mystical energy of the pyramid-shaped Rtanj Mountain. A hotspot for alternative wellness.', 'A blend of thermal recovery in Sokobanja and the mystical energy of the pyramid-shaped Rtanj Mountain. A hotspot for alternative wellness.', 'Rtanj is a geological enigma—a near-perfect pyramid rising to the Šiljak peak (1,565m). Scientists and mystics alike are drawn to its unique electromagnetic properties and its endemic plant life, notably "Rtanj Tea" (Satureja montana), which grows only on its slopes. The nearby town of Sokobanja, flourishing since the 19th century as a Romanesque air spa, provides the social and medical base for the region. Together, they offer a sophisticated blend of high-altitude adventure and restorative thermal wellness, perfect for mental and physical decompression.', 'Rtanj is a geological enigma—a near-perfect pyramid rising to the Šiljak peak (1,565m). Scientists and mystics alike are drawn to its unique electromagnetic properties and its endemic plant life, notably "Rtanj Tea" (Satureja montana), which grows only on its slopes. The nearby town of Sokobanja, flourishing since the 19th century as a Romanesque air spa, provides the social and medical base for the region. Together, they offer a sophisticated blend of high-altitude adventure and restorative thermal wellness, perfect for mental and physical decompression.', '/src/assets/images/rtanj_mountain_sokobanja_1778843487063.png', 'Weekend to 4 days', '3 hours', 180, 'Eastern Serbia', 'Eastern Serbia', '€20 - €200', 'Car', 43.7667, 21.8667, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('40', 'Zepter Hotel & Wellness', 'Zepter Hotel & Wellness', 'Wellbeing', 'A holistic wellness ecosystem in Vrnjačka Banja. Integrating luxury hospitality with preventive medicine, nutrition, and spa therapy.', 'A holistic wellness ecosystem in Vrnjačka Banja. Integrating luxury hospitality with preventive medicine, nutrition, and spa therapy.', 'Zepter Hotel in Vrnjačka Banja is a hallmark of "Health-First" luxury, integrating the Zepter group''s global health technologies like Bioptron light therapy and water ionizers into the hospitality experience. The resort focuses on preventive medicine and respiratory wellness, drawing on the region''s 2000-year thermal water history. For the Expo visitor, it provides an intellectually satisfying medical-wellness circuit that combines high-spec physical recovery, organic nutrition, and a level of specialized spa care typically found in the elite clinics of Western Europe.', 'Zepter Hotel in Vrnjačka Banja is a hallmark of "Health-First" luxury, integrating the Zepter group''s global health technologies like Bioptron light therapy and water ionizers into the hospitality experience. The resort focuses on preventive medicine and respiratory wellness, drawing on the region''s 2000-year thermal water history. For the Expo visitor, it provides an intellectually satisfying medical-wellness circuit that combines high-spec physical recovery, organic nutrition, and a level of specialized spa care typically found in the elite clinics of Western Europe.', '/src/assets/images/zepter_hotel_wellness_serbia_1778844098516.png', 'Weekend to 1 week', '3 hours', 180, 'Vrnjačka Banja', 'Vrnjačka Banja', '€150 - €600+', 'Car / Private Transfer', 43.6214, 20.8924, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('61', 'Prolom Banja', 'Prolom Banja', 'Wellbeing', 'Renowned for its unique alkaline water and southern mountain air. A destination for restorative health and metabolic wellness.', 'Renowned for its unique alkaline water and southern mountain air. A destination for restorative health and metabolic wellness.', 'Prolom Banja is globally unique for its "Prolom Water"—a highly alkaline (pH 8.8), low-mineral thermal water that originates from the depths of the Radan Mountain. Historically significant for metabolic and dermatological recovery, the spa maintains a clinical atmosphere within a pristine, zero-pollution environment. For the Expo visitor, it offers a high-value "Metabolic Reset" circuit, often combined with the geological enigma of the nearby Devil''s Town. It represents the authentic, scientifically grounded Balkan spa tradition at its most restorative and clinical peak.', 'Prolom Banja is globally unique for its "Prolom Water"—a highly alkaline (pH 8.8), low-mineral thermal water that originates from the depths of the Radan Mountain. Historically significant for metabolic and dermatological recovery, the spa maintains a clinical atmosphere within a pristine, zero-pollution environment. For the Expo visitor, it offers a high-value "Metabolic Reset" circuit, often combined with the geological enigma of the nearby Devil''s Town. It represents the authentic, scientifically grounded Balkan spa tradition at its most restorative and clinical peak.', '/src/assets/images/prolom_banja_wellness_1778846468292.png', 'Weekend to 1 week', '4 hours', 240, 'Southern Serbia', 'Southern Serbia', '€60 - €220 per night', 'Car / Private Transfer', 43.0333, 21.4, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('73', 'Herbal Pharmacies of Fruška Gora', 'Herbal Pharmacies of Fruška Gora', 'Wellbeing', 'Monastery-grade herbalism and natural wellness. Traditional remedies based on the "Holy Mountain’s" unique botanical diversity.', 'Monastery-grade herbalism and natural wellness. Traditional remedies based on the "Holy Mountain’s" unique botanical diversity.', 'Fruška Gora, the "Holy Mountain," has 16 active Orthodox monasteries that have preserved Balkan botanical wisdom since the Middle Ages. Specialized herbal pharmacies in monasteries like Kovilj and Krušedol now offer organic tinctures, monastery honey, and medicinal teas based on these centuries-old pharmaceutical recipes. These are not merely shops but centers of botanical-spiritual continuity. For the wellness explorer, they provide a sophisticated, chemical-free path to restorative health, rooted in the unique biodiversity of the region’s first National Park (est. 1960).', 'Fruška Gora, the "Holy Mountain," has 16 active Orthodox monasteries that have preserved Balkan botanical wisdom since the Middle Ages. Specialized herbal pharmacies in monasteries like Kovilj and Krušedol now offer organic tinctures, monastery honey, and medicinal teas based on these centuries-old pharmaceutical recipes. These are not merely shops but centers of botanical-spiritual continuity. For the wellness explorer, they provide a sophisticated, chemical-free path to restorative health, rooted in the unique biodiversity of the region’s first National Park (est. 1960).', '/src/assets/images/fruska_gora_herbal_pharmacy_1778847479340.png', '1 - 2 hours', '1.5 hours', 90, 'Fruška Gora Monasteries', 'Fruška Gora Monasteries', '€10 - €50', 'Car', 45.1192, 19.9405, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('14', 'Dr Kozarev Dermatology Clinic (ROI ★★★★★)', 'Dr Kozarev Dermatology Clinic (ROI ★★★★★)', 'Medical', 'Serbia’s premier dermatology center specializing in laser medicine and anti-aging with clinical credibility.', 'Serbia’s premier dermatology center specializing in laser medicine and anti-aging with clinical credibility.', 'Led by Dr. Jasmina Kozarev, a fellow of the American Academy of Dermatology with over 30 years of clinical expertise, this center is the benchmark for medical dermatology and laser technology in the region. It specializes in advanced vascular treatments, dermato-oncology (early skin cancer detection), and regenerative aesthetic medicine. For the international patient, it provides the bridge between the high-cost clinics of Switzerland and the clinical rigor of the Belgrade medical school, ensuring results backed by peer-reviewed science.', 'Led by Dr. Jasmina Kozarev, a fellow of the American Academy of Dermatology with over 30 years of clinical expertise, this center is the benchmark for medical dermatology and laser technology in the region. It specializes in advanced vascular treatments, dermato-oncology (early skin cancer detection), and regenerative aesthetic medicine. For the international patient, it provides the bridge between the high-cost clinics of Switzerland and the clinical rigor of the Belgrade medical school, ensuring results backed by peer-reviewed science.', '/src/assets/images/kozarev_clinic_facade_1778841270253.png', '1-3 hours', '15 - 20 minutes', 20, 'Belgrade, Vračar', 'Belgrade, Vračar', '€100 - €500+', 'Taxi', 44.8012, 20.4754, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('15', 'Dental Clinic Dr Popović (ROI ★★★★★)', 'Dental Clinic Dr Popović (ROI ★★★★★)', 'Medical', 'Advanced implantology and full-mouth rehabilitation for international patients at competitive costs.', 'Advanced implantology and full-mouth rehabilitation for international patients at competitive costs.', 'Under the leadership of Dr. Marko Popović, this clinic has become a hub for high-complexity oral surgery and full-mouth rehabilitation. Utilizing top-tier systems like Straumann (Switzerland) and Nobel Biocare, it offers surgical precision combined with digital CAD/CAM smile design. Their structured "Dental Tourism" protocols include airport transfers and specialized follow-up, providing a high-status medical experience that capitalizes on Belgrade''s excellent medical education and significantly more accessible pricing for titanium and zirconia restorations.', 'Under the leadership of Dr. Marko Popović, this clinic has become a hub for high-complexity oral surgery and full-mouth rehabilitation. Utilizing top-tier systems like Straumann (Switzerland) and Nobel Biocare, it offers surgical precision combined with digital CAD/CAM smile design. Their structured "Dental Tourism" protocols include airport transfers and specialized follow-up, providing a high-status medical experience that capitalizes on Belgrade''s excellent medical education and significantly more accessible pricing for titanium and zirconia restorations.', '/src/assets/images/popovic_dental_modern_1778841291195.png', '2-5 days', '15 - 20 minutes', 20, 'Belgrade, Vračar', 'Belgrade, Vračar', '€200 - €2000+', 'Taxi', 44.8025, 20.4712, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('24', 'Special Hospital Čigota', 'Special Hospital Čigota', 'Medical', 'A medical wellness institution on Zlatibor Mountain, specializing in climate therapy, nutrition, and thyroid rehabilitation.', 'A medical wellness institution on Zlatibor Mountain, specializing in climate therapy, nutrition, and thyroid rehabilitation.', 'Special Hospital Čigota is a leading medical institution in the Balkans specializing in thyroid health and metabolic disorders. Since 1989, it has implemented the world-renowned "Čigota" weight management program, integrating medical supervision with mountain-air climate therapy (at 1,000m altitude). The region''s unique "Air Spa" (Vazdušna banja) status is due to the collision of Mediterranean and Continental air currents over the Zlatibor pines. For the international patient, it offers an intellectually and clinically rigorous path to restorative health and long-term vitality.', 'Special Hospital Čigota is a leading medical institution in the Balkans specializing in thyroid health and metabolic disorders. Since 1989, it has implemented the world-renowned "Čigota" weight management program, integrating medical supervision with mountain-air climate therapy (at 1,000m altitude). The region''s unique "Air Spa" (Vazdušna banja) status is due to the collision of Mediterranean and Continental air currents over the Zlatibor pines. For the international patient, it offers an intellectually and clinically rigorous path to restorative health and long-term vitality.', '/src/assets/images/cigota_zlatibor_hospital_1778842964692.png', '3 - 14 days', '3.5 hours', 210, 'Zlatibor Mountain', 'Zlatibor Mountain', '€300 - €2000+', 'Car / Bus', 43.7258, 19.7028, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('35', 'Belgrade Regenerative Clinics', 'Belgrade Regenerative Clinics', 'Medical', 'An emerging luxury sector for advanced aesthetics and Japanese-style head spa treatments. Combining high-end medical expertise with sophisticated wellness rituals.', 'An emerging luxury sector for advanced aesthetics and Japanese-style head spa treatments. Combining high-end medical expertise with sophisticated wellness rituals.', 'Belgrade is emerging as a regional center for regenerative aesthetics, utilizing the city''s elite medical education and lower operational costs. Concepts like the "Japanese Head Spa" in the Vračar district combine trichological scalp treatments with neuromuscular relaxation and aromatherapy. High-end clinics also integrate PRP (Platelet-Rich Plasma) and stem-cell skincare with clinical rigor. For the global elite, it offers a sophisticated medical-wellness circuit where scientific results are integrated into a weekend of high-end urban recovery and sensory detox.', 'Belgrade is emerging as a regional center for regenerative aesthetics, utilizing the city''s elite medical education and lower operational costs. Concepts like the "Japanese Head Spa" in the Vračar district combine trichological scalp treatments with neuromuscular relaxation and aromatherapy. High-end clinics also integrate PRP (Platelet-Rich Plasma) and stem-cell skincare with clinical rigor. For the global elite, it offers a sophisticated medical-wellness circuit where scientific results are integrated into a weekend of high-end urban recovery and sensory detox.', '/src/assets/images/belgrade_head_spa_clinic_1778844012037.png', '1 - 3 days', 'Urban access', 20, 'Central Belgrade', 'Central Belgrade', '€40 - €2000+', 'Taxi / Private Transfer', 44.8052, 20.4648, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('43', 'Serbian Medical Rehabilitation', 'Serbian Medical Rehabilitation', 'Medical', 'World-class medical recovery and therapeutic spa infrastructure. Specializing in orthopedic and respiratory rehabilitation at accessible costs.', 'World-class medical recovery and therapeutic spa infrastructure. Specializing in orthopedic and respiratory rehabilitation at accessible costs.', 'Serbia’s rehabilitation network—including RIBARSKA BANJA (known for musculoskeletal recovery) and VRDNIK (innovative oncology wellness)—is a robust clinical infrastructure with 19 specialized hospitals. These "Banjas" combine unique mineral content with the expertise of the Belgrade Medical Faculty. Programs focus on post-operative recovery, chronic pain management, and rheumatology. For the international patient, they offer a scientifically rigorous, high-value alternative to the expensive private retreats of Switzerland, rooted in a deep European tradition of socialized medical balneology.', 'Serbia’s rehabilitation network—including RIBARSKA BANJA (known for musculoskeletal recovery) and VRDNIK (innovative oncology wellness)—is a robust clinical infrastructure with 19 specialized hospitals. These "Banjas" combine unique mineral content with the expertise of the Belgrade Medical Faculty. Programs focus on post-operative recovery, chronic pain management, and rheumatology. For the international patient, they offer a scientifically rigorous, high-value alternative to the expensive private retreats of Switzerland, rooted in a deep European tradition of socialized medical balneology.', '/src/assets/images/serbian_rehab_wellness_1778845100201.png', '1 - 3 weeks', 'Varies by location', 180, 'Multiple Spa Towns', 'Multiple Spa Towns', '€500 - €5000+', 'Car / Private Transfer', 43.6114, 20.9124, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('53', 'Beehive Air Therapy', 'Beehive Air Therapy', 'Medical', 'A holistic wellness ritual from Balkan folk medicine. Breathe in the restorative air of active beehives in peaceful rural retreats.', 'A holistic wellness ritual from Balkan folk medicine. Breathe in the restorative air of active beehives in peaceful rural retreats.', 'Apitherapy (Beehive Air Therapy) is a growing medical-wellness sector in Serbia, utilizing the antimicrobial properties of aerosol from active hives. Propolis, beeswax, and royal jelly are aerosolized by the bees'' wings and inhaled in specialized cabins, a treatment indicated for asthma, allergies, and chronic stress. This practice draws from deep Balkan folk-medicine wisdom, modernized with clinical oversight. Estates in Fruška Gora and Western Serbia offer these "Breathing Sanatoriums," providing a meditative, scientifically backed connection to the region’s ecological vitality.', 'Apitherapy (Beehive Air Therapy) is a growing medical-wellness sector in Serbia, utilizing the antimicrobial properties of aerosol from active hives. Propolis, beeswax, and royal jelly are aerosolized by the bees'' wings and inhaled in specialized cabins, a treatment indicated for asthma, allergies, and chronic stress. This practice draws from deep Balkan folk-medicine wisdom, modernized with clinical oversight. Estates in Fruška Gora and Western Serbia offer these "Breathing Sanatoriums," providing a meditative, scientifically backed connection to the region’s ecological vitality.', '/src/assets/images/beehive_air_therapy_1778845890030.png', 'Half day to weekend', 'Varies', 120, 'Multiple Rural Regions', 'Multiple Rural Regions', '€20 - €150', 'Car', 45.15, 19.85, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('86', 'Medical Package: Vrnjačka Banja Medical Spa Recovery Circuit', 'Medical Package: Vrnjačka Banja Medical Spa Recovery Circuit', 'Medical', 'Serbia’s most developed integrated wellness town, combining mineral springs, rehabilitation medicine, and thermal wellness.', 'Serbia’s most developed integrated wellness town, combining mineral springs, rehabilitation medicine, and thermal wellness.', 'Medical Package: Vrnjačka Banja is Serbia’s premier clinical-wellness town, officially recognized as a resort since 1868 by Prince Mihailo Obrenović. It combines seven mineral springs (including the unique "Warm Spring" at 36.5°C) with specialized institutions for endocrinology and metabolic health. The town’s 19th-century "Vila" architecture and 60 hectares of central parkland provide a psychologically restorative "Biedermeier" atmosphere. It is the Balkan equivalent of Karlovy Vary, offering a scientifically rigorous recovery circuit integrated into a sophisticated, slow-paced European spa culture.', 'Medical Package: Vrnjačka Banja is Serbia’s premier clinical-wellness town, officially recognized as a resort since 1868 by Prince Mihailo Obrenović. It combines seven mineral springs (including the unique "Warm Spring" at 36.5°C) with specialized institutions for endocrinology and metabolic health. The town’s 19th-century "Vila" architecture and 60 hectares of central parkland provide a psychologically restorative "Biedermeier" atmosphere. It is the Balkan equivalent of Karlovy Vary, offering a scientifically rigorous recovery circuit integrated into a sophisticated, slow-paced European spa culture.', '/src/assets/images/vrnjacka_banja_medical_spa_1778850810566.png', '3 - 10 days', '3 hours', 180, 'Central Serbia', 'Central Serbia', '€60 - €250 per night', 'Car / Private Transfer', 43.6231, 20.8953, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('87', 'Medical Package: Belgrade Dental Tourism + Danube Recovery Program', 'Medical Package: Belgrade Dental Tourism + Danube Recovery Program', 'Medical', 'World-class dentistry combined with riverside recovery in the tranquil Grocka and Vinča regions.', 'World-class dentistry combined with riverside recovery in the tranquil Grocka and Vinča regions.', 'Medical Package: This package integrates world-class dental surgery—specializing in Zirconia and Titanium implantology—with a "Danube Recovery" phase. Following procedures in Belgrade’s top-spec clinics, patients relocate to riverside villas in Grocka or Vinča (site of the 8,000-year-old Vinča culture). The soft Pannonian air and specialized "Confluence Gastronomy" (slow-cooked fish and orchard fruits) accelerate post-operative healing. It offers a refined, high-value alternative to Western dental hubs, merging clinical excellence with the unhurried lifestyle of the Danube banks.', 'Medical Package: This package integrates world-class dental surgery—specializing in Zirconia and Titanium implantology—with a "Danube Recovery" phase. Following procedures in Belgrade’s top-spec clinics, patients relocate to riverside villas in Grocka or Vinča (site of the 8,000-year-old Vinča culture). The soft Pannonian air and specialized "Confluence Gastronomy" (slow-cooked fish and orchard fruits) accelerate post-operative healing. It offers a refined, high-value alternative to Western dental hubs, merging clinical excellence with the unhurried lifestyle of the Danube banks.', '/src/assets/images/belgrade_dental_tourism_1778850826873.png', '7 - 14 days', 'Urban access', 20, 'Belgrade & Danube Riverside', 'Belgrade & Danube Riverside', '€500 - €5000+ (Procedure dependent)', 'Urban access / River shuttle', 44.8176, 20.4633, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('88', 'Medical Package: Čigota Zlatibor Metabolic Reset Program', 'Medical Package: Čigota Zlatibor Metabolic Reset Program', 'Medical', 'A legendary medical program for metabolic health and weight management in the pristine Zlatibor highlands.', 'A legendary medical program for metabolic health and weight management in the pristine Zlatibor highlands.', 'Medical Package: The Čigota Program, established in 1989 at the Special Hospital for Thyroid Gland and Metabolism, is the gold standard for metabolic health in the Balkans. At 1,000 meters altitude, it utilizes the "Zlatibor Air Spa" effect to regulate thyroid function and accelerate weight loss under strict medical supervision. The program integrates Dinaric mountain movement with a low-glycemic Mediterranean-Balkan diet. It is a scientifically grounded, no-gimmick "Life Reset" for the high-performing professional seeking to optimize metabolic performance through professional clinical oversight.', 'Medical Package: The Čigota Program, established in 1989 at the Special Hospital for Thyroid Gland and Metabolism, is the gold standard for metabolic health in the Balkans. At 1,000 meters altitude, it utilizes the "Zlatibor Air Spa" effect to regulate thyroid function and accelerate weight loss under strict medical supervision. The program integrates Dinaric mountain movement with a low-glycemic Mediterranean-Balkan diet. It is a scientifically grounded, no-gimmick "Life Reset" for the high-performing professional seeking to optimize metabolic performance through professional clinical oversight.', '/src/assets/images/cigota_zlatibor_metabolic_1778850846208.png', '7, 14, or 21 days', '3.5 hours', 210, 'Zlatibor Mountains', 'Zlatibor Mountains', '€80 - €220 per night', 'Car / Private Transfer', 43.7167, 19.7, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('89', 'Medical Package: Japanese Head Spa & Anti-Stress Belgrade Circuit', 'Medical Package: Japanese Head Spa & Anti-Stress Belgrade Circuit', 'Medical', 'Intense sensory decompression through specialized Japanese head treatments and high-end stress management.', 'Intense sensory decompression through specialized Japanese head treatments and high-end stress management.', 'Medical Package: The Japanese Head Spa circuit in Belgrade’s Vračar and Dorćol districts is a specialized sensory reset designed for cognitive overload. It combines scalp-acupressure, micro-mist technology, and artisanal aromatherapy to trigger deep parasympathetic nervous system recovery. Paired with "Floating Sauna" sessions on the Sava and low-light boutique accommodation, it provides an "Intense Sensory Sanctuary" in the heart of the city. It is the ultimate "Mind-Body Decompression" for those seeking immediate stress relief without leaving the urban cultural hubs of Belgrade.', 'Medical Package: The Japanese Head Spa circuit in Belgrade’s Vračar and Dorćol districts is a specialized sensory reset designed for cognitive overload. It combines scalp-acupressure, micro-mist technology, and artisanal aromatherapy to trigger deep parasympathetic nervous system recovery. Paired with "Floating Sauna" sessions on the Sava and low-light boutique accommodation, it provides an "Intense Sensory Sanctuary" in the heart of the city. It is the ultimate "Mind-Body Decompression" for those seeking immediate stress relief without leaving the urban cultural hubs of Belgrade.', '/src/assets/images/japanese_head_spa_belgrade_1778850862118.png', 'Half day to 2 days', 'Urban access', 10, 'Belgrade Center', 'Belgrade Center', '€60 - €200', 'On Foot / Taxi', 44.82, 20.46, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('90', 'Medical Package: Sokobanja Respiratory & Herbal Recovery Retreat', 'Medical Package: Sokobanja Respiratory & Herbal Recovery Retreat', 'Medical', 'Eastern Serbia’s "Air Spa" famous for respiratory health, radon air, and traditional herbal medicine.', 'Eastern Serbia’s "Air Spa" famous for respiratory health, radon air, and traditional herbal medicine.', 'Medical Package: Sokobanja is Serbia’s oldest "Air Spa," famous for its atmospheric pressure stability and high-radon air that benefits the respiratory and nervous systems. Housed within the shadow of the mysterious Mount Rtanj (the "Serbian Pyramid"), the resort combines thermal balneology with the region’s deep "Sacred Mountain" herbalism (Rtanj Tea). It offers a holistic, low-sensory environment for patients recovering from chronic stress or pulmonary issues, where the sound of the mountain and the traditional medical rituals provide a profound sense of recovery.', 'Medical Package: Sokobanja is Serbia’s oldest "Air Spa," famous for its atmospheric pressure stability and high-radon air that benefits the respiratory and nervous systems. Housed within the shadow of the mysterious Mount Rtanj (the "Serbian Pyramid"), the resort combines thermal balneology with the region’s deep "Sacred Mountain" herbalism (Rtanj Tea). It offers a holistic, low-sensory environment for patients recovering from chronic stress or pulmonary issues, where the sound of the mountain and the traditional medical rituals provide a profound sense of recovery.', '/src/assets/images/sokobanja_respiratory_recovery_1778850880010.png', '5 - 10 days', '3 hours', 180, 'Eastern Serbia', 'Eastern Serbia', '€50 - €180 per night', 'Car / Private Transfer', 43.6453, 21.8756, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('91', 'Medical Package: Regenerative Aesthetic Clinics + Tara Recovery', 'Medical Package: Regenerative Aesthetic Clinics + Tara Recovery', 'Medical', 'Advanced regenerative aesthetic treatments in Belgrade followed by a high-altitude forest recovery phase.', 'Advanced regenerative aesthetic treatments in Belgrade followed by a high-altitude forest recovery phase.', 'Medical Package: This package blends advanced Belgrade-based aesthetic medicine—including Bio-Regenerative PRP and laser dermatology—with a recovery phase in the high-altitude forests of the Tara National Park. The "Dermatological Forest Reset" utilizes the antimicrobial "Phytoncides" of the Tara pine forests to accelerate cellular healing. It is a high-spec integrated program where urban clinical precision meets the raw, restorative power of the Balkan wilderness, providing total privacy and a profound "New Face" and "New Mind" experience.', 'Medical Package: This package blends advanced Belgrade-based aesthetic medicine—including Bio-Regenerative PRP and laser dermatology—with a recovery phase in the high-altitude forests of the Tara National Park. The "Dermatological Forest Reset" utilizes the antimicrobial "Phytoncides" of the Tara pine forests to accelerate cellular healing. It is a high-spec integrated program where urban clinical precision meets the raw, restorative power of the Balkan wilderness, providing total privacy and a profound "New Face" and "New Mind" experience.', '/src/assets/images/regenerative_aesthetic_tara_1778850895666.png', '10 - 14 days', '4 hours (to Tara)', 240, 'Belgrade & Tara National Park', 'Belgrade & Tara National Park', '€1500 - €8000+ (Procedure dependent)', 'Private Transfer', 43.9167, 19.3833, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('92', 'Medical Package: Prolom Banja Alkaline Water Recovery', 'Medical Package: Prolom Banja Alkaline Water Recovery', 'Medical', 'A scientifically recognized destination for metabolic and renal health based on unique Prolom alkaline water.', 'A scientifically recognized destination for metabolic and renal health based on unique Prolom alkaline water.', 'Medical Package: Prolom Banja’s high-alkalinity (pH 8.8) is the center of a specialized medical circuit for renal and skin-cellular health. Located in the shadow of Mount Radan, the spa operates as a clinical sanctuary for internal detoxification. The treatment integrates Prolom water hydrotherapy with the "Zero-Noise" environment of the South Serbian mountains. For the high-status traveler, it offers a scientifically valid "Deep Cleanse" that bypasses the commercial tropes of Western detox, focusing instead on the unique geochemical properties of one of Europe’s most alkaline springs.', 'Medical Package: Prolom Banja’s high-alkalinity (pH 8.8) is the center of a specialized medical circuit for renal and skin-cellular health. Located in the shadow of Mount Radan, the spa operates as a clinical sanctuary for internal detoxification. The treatment integrates Prolom water hydrotherapy with the "Zero-Noise" environment of the South Serbian mountains. For the high-status traveler, it offers a scientifically valid "Deep Cleanse" that bypasses the commercial tropes of Western detox, focusing instead on the unique geochemical properties of one of Europe’s most alkaline springs.', '/src/assets/images/prolom_banja_alkaline_spa_1778850911305.png', '7 - 10 days', '4 hours', 240, 'Southern Serbia', 'Southern Serbia', '€60 - €220 per night', 'Car / Private Transfer', 43.0333, 21.4, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('93', 'Medical Package: Apitherapy & Beehive-Air Recovery Retreats', 'Medical Package: Apitherapy & Beehive-Air Recovery Retreats', 'Medical', 'Traditional respiratory inhalation therapy using the antimicrobial properties of active beehives in rural estates.', 'Traditional respiratory inhalation therapy using the antimicrobial properties of active beehives in rural estates.', 'Medical Package: Apitherapy (Beehive-Air Recovery) is a traditional Balkan pharmaceutical practice modernized for respiratory health. In specialized "Breathing Cabins" in the Fruška Gora or Western Serbian foothills, patients inhale air enriched by propolis, pollen, and royal jelly directly from active hives. This "Aerosolized Bio-Pharmacy" is indicated for chronic allergies and stress. The package combines the therapy with forest immersion and monastery-grade organic nutrition, offering a scientifically backed return to the ecological roots of human wellness.', 'Medical Package: Apitherapy (Beehive-Air Recovery) is a traditional Balkan pharmaceutical practice modernized for respiratory health. In specialized "Breathing Cabins" in the Fruška Gora or Western Serbian foothills, patients inhale air enriched by propolis, pollen, and royal jelly directly from active hives. This "Aerosolized Bio-Pharmacy" is indicated for chronic allergies and stress. The package combines the therapy with forest immersion and monastery-grade organic nutrition, offering a scientifically backed return to the ecological roots of human wellness.', '/src/assets/images/apitherapy_beehive_serbia_1778850928424.png', 'Half day to weekend', '1 - 2 hours', 90, 'Šumadija / Fruška Gora Regions', 'Šumadija / Fruška Gora Regions', '€30 - €150', 'Car', 44.25, 20.5833, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('94', 'Medical Package: Serbian Thermal Spa Grand Tour', 'Medical Package: Serbian Thermal Spa Grand Tour', 'Medical', 'A comprehensive medical tour across Serbia’s most significant thermal springs and recovery towns.', 'A comprehensive medical tour across Serbia’s most significant thermal springs and recovery towns.', 'Medical Package: The Serbian Thermal Spa Grand Tour is a 14-day clinical-historical odyssey across the nation’s 19th-century and Ottoman balneological hubs. It connects Vrnjačka, Sokobanja, and Bukovicka Banja (near the Oplenac royal site) into a single restorative narrative. The tour evaluates the specific mineral "Terroir" of each spring, tailoring treatments to the user’s longevity and performance goals. It is the most comprehensive "Medical Discovery" route in the Balkans, merging imperial history, royal viticulture, and the peak of European balneology.', 'Medical Package: The Serbian Thermal Spa Grand Tour is a 14-day clinical-historical odyssey across the nation’s 19th-century and Ottoman balneological hubs. It connects Vrnjačka, Sokobanja, and Bukovicka Banja (near the Oplenac royal site) into a single restorative narrative. The tour evaluates the specific mineral "Terroir" of each spring, tailoring treatments to the user’s longevity and performance goals. It is the most comprehensive "Medical Discovery" route in the Balkans, merging imperial history, royal viticulture, and the peak of European balneology.', '/src/assets/images/serbian_thermal_spa_tour_1778850947138.png', '10 - 14 days', 'Varies', 180, 'Multi-region Serbia', 'Multi-region Serbia', '€800 - €3000', 'Private Driver / Car', 43.6231, 20.8953, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('95', 'Medical Package: Longevity & Slow Aging Retreat — Fruška Gora', 'Medical Package: Longevity & Slow Aging Retreat — Fruška Gora', 'Medical', 'A science-backed retreat focusing on longevity, anti-inflammatory nutrition, and monastery-inspired silence.', 'A science-backed retreat focusing on longevity, anti-inflammatory nutrition, and monastery-inspired silence.', 'Medical Package: This retreat in the "Serbian Holy Mountain" of Fruška Gora is a science-backed "Slow-Aging" intervention. It merges intermittent fasting strategies with Pannonian "Salaš" nutrition and the proven cognitive benefits of forest bathing and monastery-integrated stillness. The package focuses on reducing systemic inflammation and optimizing "Healthspan" through a combination of local bio-products, e-bike movement, and deep ecological connection. It is the pinnacle of the "New Serbian Wellness" movement, where historical depth meets modern longevity science.', 'Medical Package: This retreat in the "Serbian Holy Mountain" of Fruška Gora is a science-backed "Slow-Aging" intervention. It merges intermittent fasting strategies with Pannonian "Salaš" nutrition and the proven cognitive benefits of forest bathing and monastery-integrated stillness. The package focuses on reducing systemic inflammation and optimizing "Healthspan" through a combination of local bio-products, e-bike movement, and deep ecological connection. It is the pinnacle of the "New Serbian Wellness" movement, where historical depth meets modern longevity science.', '/src/assets/images/fruska_gora_longevity_retreat_1778850964231.png', '5 - 7 days', '1.5 hours', 90, 'Fruška Gora', 'Fruška Gora', '€180 - €500 per night', 'Car / Private Transfer', 45.15, 19.85, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('3', 'Belgrade Waterfront Clubbing', 'Noćni život na rekama', 'Clubbing', 'Experience the world-renowned energy of Belgrade’s nightlife at the confluence of the Sava and Danube rivers. From sophisticated house music boat clubs (splavovi) to underground industrial venues, Belgrade offers a pulse that doesn’t stop until sunrise, blending grit with high-end luxury.', 'Iskusite svetski poznatu energiju beogradskog noćnog života na ušću Save u Dunav.', 'Belgrade is the undisputed "New Berlin" of European nightlife, inheriting a rebellious energy from the 1990s. The scene is defined by "splavovi"—floating clubs permanently moored along the Sava and Danube. Iconic spots like 20/44 (named after its coordinates) offer high-end house and techno, while the Beton Hala (Concrete Hall) district features refined restaurants that transition into elite clubs. The district also encompasses the historic Savamala area, where 19th-century architecture meets industrial grit. Whether at the "Confluence" awaiting the sunrise or in the dark booths of Hangar, Belgrade’s nightlife is a sophisticated, hedonistic journey through the city’s resilient spirit.', 'Beograd se često naziva ''novim Berlinom'' noćnog života. Scena je koncentrisana na splavovima - plutajućim klubovima na obalama reka. Tokom leta, ovi splavovi su epicentar energije grada, nudeći sve od tehna do lokalnog popa.', '/src/assets/images/belgrade_splavovi_1778841081901.png', '6+ hours', '15 - 30 minutes', 20, 'Belgrade', 'Beograd', '€20 - €100+', 'Taxi / Foot', 44.8142, 20.4497, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('23', 'Silosi Belgrade', 'Silosi Belgrade', 'Clubbing', 'Industrial culture at its finest. Former grain silos on the Danube transformed into a hub for art installations, electronic music, and urban regeneration.', 'Industrial culture at its finest. Former grain silos on the Danube transformed into a hub for art installations, electronic music, and urban regeneration.', 'Silosi Belgrade is a monumental industrial landmark and a hub for the "Gaia Movement" (Gaia Pokret) non-profit. These four massive 28-meter high grain silos, once symbols of 20th-century Yugoslav logistics, now serve as platforms for education, ecology, and avant-garde art. Known for their brutalist acoustics, they host experimental electronic music and large-scale art installations. For the urban explorer, Silosi represents the organic "soft power" of Belgrade, blending industrial grit with a sophisticated commitment to cultural and environmental dialogue on the Danube bank.', 'Silosi Belgrade is a monumental industrial landmark and a hub for the "Gaia Movement" (Gaia Pokret) non-profit. These four massive 28-meter high grain silos, once symbols of 20th-century Yugoslav logistics, now serve as platforms for education, ecology, and avant-garde art. Known for their brutalist acoustics, they host experimental electronic music and large-scale art installations. For the urban explorer, Silosi represents the organic "soft power" of Belgrade, blending industrial grit with a sophisticated commitment to cultural and environmental dialogue on the Danube bank.', '/src/assets/images/silosi_belgrade_industrial_night_1778842947193.png', 'Evening to late night', '15 - 25 minutes', 20, 'Dorćol, Belgrade', 'Dorćol, Belgrade', '€40 - €150', 'Taxi / Rideshare', 44.8322, 20.4658, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('31', 'Drugstore Belgrade', 'Drugstore Belgrade', 'Clubbing', 'A "Techno Cathedral" housed in a former industrial plant. The epicenter of Belgrade’s raw, underground electronic music reputation.', 'A "Techno Cathedral" housed in a former industrial plant. The epicenter of Belgrade’s raw, underground electronic music reputation.', 'Drugstore is Belgrade’s "Bunker Cathedral" of electronic music, located in a massive former slaughterhouse in the Palilula district. Its brutalist concrete pillars and cavernous spaces have become the canvas for the city’s most intellectually daring club nights and art performances. Unlike commercial venues, it prioritizes sound quality and the "Industrial Romanticism" of the Danube’s working-class history. For the traveler seeking the "True Underground," Drugstore provides a raw, unapologetic experience of Belgrade’s resilient, alternative creative soul.', 'Drugstore is Belgrade’s "Bunker Cathedral" of electronic music, located in a massive former slaughterhouse in the Palilula district. Its brutalist concrete pillars and cavernous spaces have become the canvas for the city’s most intellectually daring club nights and art performances. Unlike commercial venues, it prioritizes sound quality and the "Industrial Romanticism" of the Danube’s working-class history. For the traveler seeking the "True Underground," Drugstore provides a raw, unapologetic experience of Belgrade’s resilient, alternative creative soul.', '/src/assets/images/drugstore_belgrade_club_1778843533726.png', 'Late night to sunrise', 'Urban access', 25, 'Palilula, Belgrade', 'Palilula, Belgrade', '€30 - €120', 'Taxi / Rideshare', 44.8219, 20.4897, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('39', 'Hype Belgrade', 'Hype Belgrade', 'Clubbing', 'Polished riverside splav culture at its peak. Belgrade’s signature high-end nightlife experience featuring sophisticated music and river perspectives.', 'Polished riverside splav culture at its peak. Belgrade’s signature high-end nightlife experience featuring sophisticated music and river perspectives.', 'Hype is the premier "LoungeSplav" in Belgrade, catering to the city''s high-society and international professional circles. Located at the prestigious Sava waterfront, it moves beyond the warehouse-rave aesthetic in favor of high-spec lighting, specialized mixology, and a 360-degree view of the illuminated Belgrade Fortress. It represents the "Social Frontier" of Belgrade, where contemporary global lifestyle meets the city''s legendary river energy. For the visitor, it offers a refined, high-status gateway into the most vibrant nightlife capital of Southeast Europe.', 'Hype is the premier "LoungeSplav" in Belgrade, catering to the city''s high-society and international professional circles. Located at the prestigious Sava waterfront, it moves beyond the warehouse-rave aesthetic in favor of high-spec lighting, specialized mixology, and a 360-degree view of the illuminated Belgrade Fortress. It represents the "Social Frontier" of Belgrade, where contemporary global lifestyle meets the city''s legendary river energy. For the visitor, it offers a refined, high-status gateway into the most vibrant nightlife capital of Southeast Europe.', '/src/assets/images/hype_belgrade_splav_luxury_1778844082665.png', 'Late evening to sunrise', 'Urban access', 20, 'Sava Riverfront, Belgrade', 'Sava Riverfront, Belgrade', '€50 - €300+', 'Taxi / Rideshare', 44.8152, 20.4488, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('41', 'Humska Cigar Lounge', 'Humska Cigar Lounge', 'Clubbing', 'Refined urban evening culture focusing on premium whiskies and cigars. A quieter, sophisticated alternative to Belgrade’s high-energy club scene.', 'Refined urban evening culture focusing on premium whiskies and cigars. A quieter, sophisticated alternative to Belgrade’s high-energy club scene.', 'Humska Cigar Lounge is the spiritual home of Belgrade''s old-world elite, located in the prestigious Senjak and Vračar residential districts. Designed with deep leather club chairs and dark wood, it operates as a private sanctuary for diplomats, business leaders, and the culturally engaged who seek a "Slow Evening." The lounge features an expertly curated list of aged Single Malts and premium Cuban and Nicaraguan puros. It provides an intellectually quiet and sophisticated alternative to the high-tempo riverfront scene, emphasizing the Balkan ritual of unhurried social dialogue.', 'Humska Cigar Lounge is the spiritual home of Belgrade''s old-world elite, located in the prestigious Senjak and Vračar residential districts. Designed with deep leather club chairs and dark wood, it operates as a private sanctuary for diplomats, business leaders, and the culturally engaged who seek a "Slow Evening." The lounge features an expertly curated list of aged Single Malts and premium Cuban and Nicaraguan puros. It provides an intellectually quiet and sophisticated alternative to the high-tempo riverfront scene, emphasizing the Balkan ritual of unhurried social dialogue.', '/src/assets/images/humska_whisky_lounge_1778845065740.png', 'Evening', 'Urban access', 15, 'Senjak / Vračar, Belgrade', 'Senjak / Vračar, Belgrade', '€40 - €250', 'Taxi', 44.7952, 20.4488, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('51', 'Belgrade Design Districts', 'Belgrade Design Districts', 'Clubbing', 'The creative pulse of the city. Former breweries and warehouses in Cetinjska and Dorćol transformed into hubs of art, bars, and urban culture.', 'The creative pulse of the city. Former breweries and warehouses in Cetinjska and Dorćol transformed into hubs of art, bars, and urban culture.', 'Belgrade’s design districts—Cetinjska and the Dorćol hubs—are the epicenters of the city’s "New Creative Economy." Cetinjska, a former beer brewery complex, houses a cluster of bars, galleries, and jazz clubs like "Zappa" and "Sprat." These "Urban Creative Villages" were popularized by trailblazers like "Supermarket" (the city’s first concept store). For the visitor, they offer a visceral sense of Belgrade’s resilience, where industrial decay has been repurposed into high-end cultural dialogue, attracting a cosmopolitan crowd of artists, tech founders, and journalists.', 'Belgrade’s design districts—Cetinjska and the Dorćol hubs—are the epicenters of the city’s "New Creative Economy." Cetinjska, a former beer brewery complex, houses a cluster of bars, galleries, and jazz clubs like "Zappa" and "Sprat." These "Urban Creative Villages" were popularized by trailblazers like "Supermarket" (the city’s first concept store). For the visitor, they offer a visceral sense of Belgrade’s resilience, where industrial decay has been repurposed into high-end cultural dialogue, attracting a cosmopolitan crowd of artists, tech founders, and journalists.', '/src/assets/images/belgrade_design_district_1778845854594.png', 'Evening to late night', 'Urban access', 15, 'Dorćol / Cetinjska, Belgrade', 'Dorćol / Cetinjska, Belgrade', '€20 - €100+', 'On Foot / Taxi', 44.8252, 20.4638, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('60', 'Belgrade Waterfront Rooftops', 'Belgrade Waterfront Rooftops', 'Clubbing, Gastronomy', 'The pinnacle of contemporary Belgrade urbanism. High-end rooftop bars and fine dining with spectacular reflections on the Sava river.', 'The pinnacle of contemporary Belgrade urbanism. High-end rooftop bars and fine dining with spectacular reflections on the Sava river.', 'Belgrade Waterfront (Beograd na vodi) is the most ambitious urban transformation project in Southeast Europe. Its high-end dining and bar scene—focused around the Sava Promenade and the "Terraces"—represents the city''s new cosmopolitan center of gravity. Venues like the "Sky Drina" and the "Residences at St. Regis" offer pano-views of the river confluence and the historic bridge-scape. It is the essential "Front-Row Seat" for the new, high-performing Belgrade, blending global luxury standards with the city''s legendary river vitality.', 'Belgrade Waterfront (Beograd na vodi) is the most ambitious urban transformation project in Southeast Europe. Its high-end dining and bar scene—focused around the Sava Promenade and the "Terraces"—represents the city''s new cosmopolitan center of gravity. Venues like the "Sky Drina" and the "Residences at St. Regis" offer pano-views of the river confluence and the historic bridge-scape. It is the essential "Front-Row Seat" for the new, high-performing Belgrade, blending global luxury standards with the city''s legendary river vitality.', '/src/assets/images/belgrade_waterfront_rooftop_1778846450339.png', 'Evening to late night', 'Urban access', 10, 'Sava Riverfront, Belgrade', 'Sava Riverfront, Belgrade', '€40 - €250+', 'On Foot / Taxi', 44.8082, 20.4528, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('71', 'Belgrade Jazz Festival Venues', 'Belgrade Jazz Festival Venues', 'Clubbing, Gastronomy', 'A sophisticated tradition since 1971. Experience world-class jazz in the city’s most elegant halls and basement clubs.', 'A sophisticated tradition since 1971. Experience world-class jazz in the city’s most elegant halls and basement clubs.', 'Belgrade has deep jazz heritage, with its first international festival launching in 1971 at the height of the Non-Aligned Movement. The city has hosted legends like Miles Davis, Ella Fitzgerald, and Duke Ellington. Venues like Dom Omladine (Belgrades Cultural Center) and the historic MTS Hall serve as formal theaters, while the "Underground Club Circuit" in the city center preserves the improvisational soul of the 1950s and 60s. For the sophisticated traveler, Belgrade Jazz is an intellectually engaged, cosmopolitan bridge to the city’s complex, high-performing artistic past.', 'Belgrade has deep jazz heritage, with its first international festival launching in 1971 at the height of the Non-Aligned Movement. The city has hosted legends like Miles Davis, Ella Fitzgerald, and Duke Ellington. Venues like Dom Omladine (Belgrades Cultural Center) and the historic MTS Hall serve as formal theaters, while the "Underground Club Circuit" in the city center preserves the improvisational soul of the 1950s and 60s. For the sophisticated traveler, Belgrade Jazz is an intellectually engaged, cosmopolitan bridge to the city’s complex, high-performing artistic past.', '/src/assets/images/belgrade_jazz_club_atmosphere_1778847420275.png', 'Evening', 'Urban access', 10, 'City Center, Belgrade', 'City Center, Belgrade', '€15 - €50', 'On Foot / Taxi', 44.815, 20.46, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('98', 'Arsenal Fest', 'Arsenal Fest Kragujevac', 'Clubbing', 'An atmospheric music festival inside a dramatic 19th-century military-industrial complex in Kragujevac.', 'Muzički festival smešten u jedinstvenom istorijskom kompleksu Kneževog arsenala iz 19. veka.', 'Arsenal Fest takes place within the walls of a beautifully preserved Austro-Hungarian military refinery called "Knežev Arsenal" in the town of Kragujevac. This rustic brick fortress under massive industrial-era chimneys creates a unique acoustic reflection and visual synergy for live music spectacles. Heavy laser installations over aged brick walls and a high-status rock and electronic lineup provide EXPO visitors with a raw, powerful, and deeply authentic Serbian festival experience outside of Belgrade.', 'Arsenal Fest održava se u srcu Kragujevca, u unutrašnjosti autentičnog austrougarskog vojnog kompleksa ''Knežev arsenal''. Sa zidinama od crvene cigle i masivnim dimnjacima, ovaj prostor stvara neverovatan kontrast rock sceni i klupskom ozvučenju. Poznat po visokoj energiji i sjajnom line-upu, festival predstavlja dragoceno industrijsko nasleđe i sirovu snagu autentičnog Šumadijskog gostoprimstva van Beograda.', '/src/assets/images/arsenal_fest_1779796252730.png', '1 - 3 days', '1.5 hours', 90, 'Kragujevac, Central Serbia', 'Kragujevac', '€30 - €80', 'Car / Private Driver', 44.0128, 20.9114, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('99', 'EXIT Festival', 'EXIT Festival Novi Sad', 'Clubbing', 'Serbia’s world-famous music festival set inside the stone Petrovaradin Fortress over the Danube.', 'Legendarni i svetski poznat muzički festival na Petrovaradinskoj tvrđavi iznad Dunava.', 'EXIT is a multi-award-winning music festival set inside Novi Sad’s historic 17th-century Petrovaradin Fortress. Famous for its pristine acoustics from defensive military layouts, the Dance Arena is globally recognized as one of the best electronic music stages on Earth. It is a key networking event, drawing tens of thousands of young tech founders, designers, and creatives from Central and Western Europe. Just a 35-minute bullet-train (Soko) ride from Belgrade during the summer EXPO window.', 'EXIT je jedan od najčuvenijih muzičkih festivala na svetu, održan na zidinama veličanstvene Petrovaradinske tvrđave iz 17. veka u Novom Sadu. Poznat po izuzetnoj akustici, Dance Areni svetskog nivoa i neverovatnoj sinergiji, EXIT okuplja stotine hiljada ljudi, uključujući i evropsku tech, medijsku i preduzetničku elitu. Odličan jednodnevni izlet brzim vozom ''Soko'' iz Beograda.', '/src/assets/images/exit_festival_1779796272417.png', 'Full day to 4 days', '1 hour', 60, 'Novi Sad / Petrovaradin', 'Novi Sad', '€50 - €250', 'Intercity Fast Train (Soko)', 45.2531, 19.8624, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('100', 'Lovefest', 'Lovefest Vrnjačka Banja', 'Clubbing', 'An outstanding electronic music festival floating among the thermal spa forests and lakes of Vrnjačka Banja.', 'Spektakularni muzički festival u gustoj banjskoj šumi, idealan spoj klupske energije i spa relaksacije.', 'Lovefest brings premium electronic clubbing energy to the scenic green park forests of Vrnjačka Banja. Taking place around natural spring lakes under centuries-old towering trees, the festival offers an incredible contrast between night-long electronic dance events and restorative balneotherapy during the day in local luxury wellness centers. It serves as a sublime, refreshing summer escape for EXPO business delegates looking to pair youthful networking with total spa recovery.', 'Lovefest spaja vrhunski klupski zvuk sa opuštenom atmosferom najzelenijeg dela Vrnjačke Banje. Održava se pored jezera na lokaciji okruženoj stoletnim drvećem, a njegovi posetioci uživaju u kontrastu između celonoćnog plesa i dnevne balneo-terapije u lokalnim termalnim izvorima. Savršen beg za posetioce festivala i wellness putnike koji traže opušten, revitalizujući letnji vikend.', '/src/assets/images/lovefest_1779796296636.png', 'Full day to weekend', '3 hours', 180, 'Vrnjačka Banja', 'Vrnjačka Banja', '€40 - €150', 'Car / Private Transfer', 43.6214, 20.8924, NULL, NULL, NULL, NULL, NULL, NULL, TRUE),
('102', 'Belgrade Beer Fest', 'Belgrade Beer Fest', 'Clubbing', 'Colossal open-air riverside social gathering featuring domestic brewing options, global acts, and local street-food networking.', 'Masovni muzički i pivski festival na ušću Save u Dunav, idealan za opušteno umrežavanje i uličnu hranu.', 'Belgrade Beer Fest is one of Southeast Europe’s largest mass open-air social events, located at the beautiful "Ušće" confluence of the Sava and Danube rivers. Gaze across the water at the illuminated Belgrade Fortress while sampling regional craft beers, enjoying concerts, and experiencing traditional Serbian grilled sausages. It offers a premium opportunity for relaxed, large-team networking and nearness to natural water vitalities right in the center of Belgrade.', 'Belgrade Beer Fest je jedan od najvećih masovnih festivala u jugoistočnoj Evropi, smešten na slikovitom travnatom Ušću gde se Sava susreće sa Dunavom. Pod otvorenim beogradskim letnjim nebom, festival nudi stotine vrsta domaćih i zanatskih piva, uličnu hranu i fantastičnu atmosferu. Savršen je izbor za neformalni tim-bilding, opušten razgovor nakon zvaničnih sastanaka i vizuelno impresivno iskustvo beogradskog rečnog života.', '/src/assets/images/belgrade_beer_fest_1779796340949.png', 'Late evening to midnight', 'Urban access', 10, 'Ušće Confluence, Belgrade', 'Ušće, Beograd', 'Free - €40', 'Taxi / Walking', 44.8231, 20.4372, NULL, NULL, NULL, NULL, NULL, NULL, TRUE)
